{"code":"AIIS 128","title":"Indigenous Lifeways","department":"American Indian & Indigen Std","credits":1,"description":"This course explores many of the questions that come to mind when we think about the diverse lifeways of Indigenous Peoples around the world. This course includes perspectives from Native American and Indigenous Studies and a variety of other disciplines.","cross_listed":["AMST 128"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/aiis-american-indian-and-indigenous-studies/100/aiis-128","sections":[{"days":"TR","room":"202","types":[],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"202","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"202","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["J. Seth T. Schermerhorn"]}]},
{"code":"ALSO 141","title":"First Term Korean","department":"Alternative Language Stdy Optn","credits":0.5,"description":"Novice-level introduction to Korean language with emphasis on verbal proficiency, reading and listening comprehension. ALSO courses combine self-instruction with peer tutor facilitation. Twice weekly tutor-led class sessions are highly interactive and conducted almost entirely in the target language. Midterm and final exams, administered by external examiners, determine course grades. Midterm and final exams conducted by outside examiner.","cross_listed":[],"catalog_url":null,"sections":[{"days":"TR","room":"211","types":[],"status":"open","section":"01","building":"Burke Library","capacity":10,"comments":null,"end_time":"17:00:00","meetings":[{"days":"TR","room":"211","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"17:00","start_date":"2026-08-27","start_time":"16:00"}],"start_time":"16:00:00","instructors":["Claire Frances"]}]},
