{"code":"BIO 211","title":"Genes, Molecules, & Cells","department":"Biology","credits":1,"description":"An intermediate course that examines genetics and biochemistry within the context of the cell. This course will focus on the macromolecules of life, genetic material and classical genetics, fundamental biochemical pathways, and cellular structure and function. A particular focus will be placed on proteins and nucleic acids and how cells use these molecules to direct the mechanisms of inheritance, energy production, and cellular reproduction. Three hours of class and three hours of laboratory.","cross_listed":["NEURO 211"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-211","sections":[{"days":"TR","room":"3024","types":["Quantitative & Symbolic R","Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Sophomores only. Not open to those who took BIO 248. Must also register for BIO 211 lab section.","end_time":"10:15:00","meetings":[{"days":"TR","room":"3024","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3024","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Ivan Bochkov"]}]},
