{"code":"BIO 290","title":"Paleontology","department":"Biology","credits":1,"description":"A study of the history of life, evolution and the fossil record. Topics include the general principles of paleontology, nomenclature, taxonomy, identification techniques, fossilization processes, plants, microfossils, invertebrates and vertebrates. Three hours of class and three hours of laboratory with field trips.","cross_listed":["GEOSC 290"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-290","sections":[{"days":"MWF","room":"1011","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":"Open to Seniors, Juniors, & Sophomores","end_time":"10:50:00","meetings":[{"days":"MWF","room":"1011","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"1011","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"1011","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Kristopher M. Kusnerik"]}]},
{"code":"BIO 298","title":"Biology Research","department":"Biology","credits":0.25,"description":"Independent research under the supervision of a faculty member. May be repeated for credit. Students may count up to one credit of biology research toward the concentration. One-quarter, one-half, or one credit per semester. No senior concentrators.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/200/bio-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Andrea K. Townsend"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ariel F. Kahrl"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Wei-Jen Chang"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ivan Bochkov"]},{"days":null,"room":null,"types":[],"status":"open","section":"05","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Jason M. Townsend"]},{"days":null,"room":null,"types":[],"status":"open","section":"06","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Pete Guiden"]},{"days":null,"room":null,"types":[],"status":"open","section":"07","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Michael L. McCormick"]},{"days":null,"room":null,"types":[],"status":"open","section":"08","building":null,"capacity":40,"comments":null,"end_time":null,"meetin