{"code":"BIO 331","title":"Physiology","department":"Biology","credits":1,"description":"In this course we will explore the basic principles of physiology and homeostasis focusing on mammalian/human systems and will occasionally explore physiological adaptations in other vertebrate systems. This course will provide a solid foundation in critical thinking, research methods, and data analysis while covering physiological systems including osmoregulation, respiration, digestion, circulation, nerve and muscle function, hormones, immune function, and reproduction.","cross_listed":["NEURO 331"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/300/bio-331","sections":[{"days":"MWF","room":"2048","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"2048","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"2048","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Ariel F. Kahrl"]}]},
