{"code":"BIO 346","title":"Biochemistry","department":"Biology","credits":1,"description":"The advanced study of biochemical pathways in living organisms, with emphasis given to gene regulation and metabolism of four major macromolecules: carbohydrates, lipids, proteins and nucleic acids. Includes in-depth discussion of contemporary developments in molecular biology and comprehensive training in molecular techniques. Three hours of class and three hours of laboratory.","cross_listed":["BICHM 346"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/bio-biology/300/bio-346","sections":[{"days":"MWF","room":"104","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Benedict Hall","capacity":30,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"104","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"104","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Wei-Jen Chang"]},{"days":"MWF","room":"104","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"02","building":"Benedict Hall","capacity":30,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"104","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"104","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Wei-Jen Chang"]}]},
