{"code":"CHEM 263","title":"Quant Environ Chemistry","department":"Chemistry","credits":1,"description":"A survey of the environmental chemistry of natural and polluted systems, including equilibrium, solubility, activity, mass and charge balance, and oxidation-reduction. Theory and techniques from analytical chemistry, including gravimetric analysis, volumetric analysis, potentiometric analysis, and chromatographic methods. Laboratories emphasize quantitative analytical techniques.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/200/chem-263","sections":[{"days":"TR","room":"G042","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Seniors, Juniors, Sophomores Only","end_time":"11:45:00","meetings":[{"days":"TR","room":"G042","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"G042","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Carolyn P. Hutchinson"]}]},
