{"code":"CHEM 321","title":"Physical Chemistry I","department":"Chemistry","credits":1,"description":"A study of the fundamental concepts and principles of quantum chemistry. Topics include the fundamental postulates of quantum mechanics, the nature of the chemical bond, and applications of molecular quantum mechanics including spectroscopy and computational electronic structure methods.","cross_listed":["BICHM 321"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-321","sections":[{"days":"MWF","room":"207","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Benedict Hall","capacity":40,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Adam W. Van Wynsberghe"]}]},
{"code":"CHEM 325","title":"Physical Method Chem Analysis","department":"Chemistry","credits":1,"description":"An integrated lecture-laboratory course in which students learn to design, build, and use instrumentation to study the physicochemical properties of atoms and molecules. Topics include the theory and practice of optical spectroscopy, thermochemical measurements of gases and condensed phases, and the measurement of reaction kinetics. Evaluations stress mastery of laboratory technique and communication of results with an emphasis on oral communication. Speaking-Intensive. One hour of lecture, three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-325","sections":[{"days":"M","room":"1052","types":["Quantitative & Symbolic R","Speaking Intensive Course"],"status":"open","section":"01","building":"Taylor Science Center","capacity":12,"comments":null,"end_time":"12:50:00","meetings":[{"days":"M","room":"1052","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"},{"days":"M","room":"1052","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"}],"start_time":"12:00:00","instructors":["Wesley W. Kramer"]}]},
{"code":"CHEM 326","title":"Chemistry of Catastrophe","department":"Chemistry","credits":0.5,"description":"An exploration of both the chemistry and the social impacts of several major environmental disasters, such as Love Canal, the Deep Water Horizon spill, the Seveso accident, and the Chernobyl disaster.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-326","sections":[{"days":"WF","room":"G042","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":12,"comments":"Open to CHEM concentrators only. Course runs 10/23/26-12/18/26. 0.5 credit","end_time":"14:15:00","meetings":[{"days":"WF","room":"G042","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-10-23","start_time":"13:00"},{"days":"R","room":"G042","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Carolyn P. Hutchinson"]}]},
{"code":"CHEM 344","title":"Chemical Approach to Solar En","department":"Chemistry","credits":0.5,"description":"An introduction to the fundamental electro- and photochemical processes that enable harvesting of solar energy. Topics to be addressed will include the theory and application of semiconductor materials as solar cells to capture light energy, as well as the electrochemical processes that enable the storage of that energy as solar fuels (artificial photosynthesis) or in grid scale batteries. The course will revolve around readings from the primary chemical literature. One-half credit seminar.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-344","sections":[{"days":"WF","room":"G042","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":12,"comments":"Open to CHEM concentrators only. Course runs 8/27/26-10/21/26. 0.5 credit","end_time":"14:15:00","meetings":[{"days":"WF","room":"G042","type":"LEC","building":"Taylor Science Center","end_date":"2026-10-21","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Wesley W. Kramer"]}]},
{"code":"CHEM 371W","title":"Research Methods in Chem","department":"Chemistry","credits":1,"description":"Development of research skills in chemistry through a semester-long intensive laboratory project. Emphasis on laboratory work focusing on advanced synthetic techniques and spectroscopic characterization. Scientific writing, oral presentation skills and use of the chemical literature are also stressed. Six hours of laboratory and one hour of class. Prerequisites, 265 or 270.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/chem-chemistry/300/chem-371","sections":[{"days":"T","room":"1052","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"T","room":"1052","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"1052","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"12:00"},{"days":"F","room":"1052","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Max M. Majireck","Michael A. Welsh"]}]},
