{"code":"CPSCI 200","title":"Ssih Course","department":"Computer Science","credits":0,"description":"This course is taken concurrently with a course approved for the student by the department that aims to satisfy the department's Social, Structural, and Institutional Hierarchies requirement. Satisfactory completion of this course requires successful completion of the approved course. This course should be completed by the end of the student's junior year. Open to concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/200/cpsci-200","sections":[{"days":null,"room":null,"types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to CPSCI concentrators only.","end_time":null,"meetings":[],"start_time":null,"instructors":["Darren J. Strash"]}]},
{"code":"CPSCI 220","title":"Prin Programming Lang","department":"Computer Science","credits":1,"description":"Investigation into the nature, features, design and implementation of programming languages. Students will gain experience with a wide variety of programming languages through programming exercises. Topics will include, among others, object-oriented programming, functional programming, higher-order functions, type systems and polymorphism.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/200/cpsci-220","sections":[{"days":"MWF","room":"2017","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"2017","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"2017","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Karyn Doke"]}]},
{"code":"CPSCI 230","title":"Algorithms & Data Structures","department":"Computer Science","credits":1,"description":"A study of fundamental algorithms and data structures from the canon, emphasizing correctness, and trade-offs between techniques, alongside deliberate coverage of topics from discrete mathematics. Topics include running time and space analysis, invariants as a means of proving correctness, and the divide-and-conquer, greedy, and dynamic programming algorithm design paradigms. Specific problems include graph traversals, (optimal) sorting/searching, minimum spanning tree and shortest paths, longest common subsequences, balanced search trees, heaps, hashing, and union-find for disjoint sets.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/200/cpsci-230","sections":[{"days":"MWF","room":"1004","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"13:50:00","meetings":[{"days":"MWF","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Shawn Chen"]}]},
{"code":"CPSCI 240","title":"Computer Organization","department":"Computer Science","credits":1,"description":"A study of the connection between high-level programs and the machines on which they run by means of extensive programming experience using assembly language. Topics will include translation of high-level language idioms into assembly language, number systems and representation schemes, exceptions, interrupts, polling, and an introduction to the structure of the underlying hardware. In the final project, students develop an assembler.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/200/cpsci-240","sections":[{"days":"MWF","room":"1004","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Han Dong"]}]},
{"code":"CPSCI 298","title":"Computer Science Research","department":"Computer Science","credits":0.25,"description":"Independent work on a research project under supervision of a faculty member.\n\nStudents may repeat 298 for credit, but only a maximum of one credit of Computer Science Research can count towards satisfying the requirements for departmental honors.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/200/cpsci-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Sarah Morrison-Smith"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Darren J. Strash"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Han Dong"]}]},
{"code":"CPSCI 340","title":"Operating Systems","department":"Computer Science","credits":1,"description":"Study of the design and implementation of computer operating systems. Students will develop at least four significant projects related to the topics of process scheduling, interprocess communication, memory management, file systems, access control, device drivers and security. Programming intensive.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/300/cpsci-340","sections":[{"days":"MWF","room":"3040","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"3040","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"3040","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Han Dong"]}]},
{"code":"CPSCI 360","title":"Dev Accessible User Interface","department":"Computer Science","credits":1,"description":"Introduction to access technology and the development of accessible systems. In this course, students build and evaluate various access technologies. This course teaches students the deep inner workings of today's user interface technology and serves as a guide for building the user interfaces of the future. Topics include: text-to-speech, speech recognition, screen readers, screen magnification, alternative input, tactile displays, and web transformation. Programming intensive.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/300/cpsci-360","sections":[{"days":"MWF","room":"3040","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":"Open to CPSCI concentrators only","end_time":"13:50:00","meetings":[{"days":"MWF","room":"3040","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"3040","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Sarah Morrison-Smith"]}]},
{"code":"CPSCI 366","title":"Deep Learning","department":"Computer Science","credits":1,"description":"This course covers deep learning fundamentals, from core machine learning concepts (e.g.: loss functions, bias-variance, and optimization) to advanced models like Multilayer Perceptrons, Convolutional Neural Networks, Recurrent Neural Networks, and Transformers. Students will gain hands-on experience by applying these techniques to real-world datasets using various deep learning frameworks.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/300/cpsci-366","sections":[{"days":"MW","room":"1004","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Shawn Chen"]}]},
{"code":"CPSCI 375","title":"Artificial Intelligence","department":"Computer Science","credits":1,"description":"Introduction to the theory and implementation of artificial intelligence. This course covers both foundational and modern approaches to AI, and explores a common thread of searching intelligently for solutions. Students will learn to select an appropriate AI representation to solve a problem and empirically analyze the performance of AI systems. Topics include heuristic search, game playing, evolutionary computation, machine learning, and the ethics of artificial intelligence. Programming Intensive.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/300/cpsci-375","sections":[{"days":"MWF","room":"309","types":[],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":24,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"309","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"309","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Christina Ji"]}]},
{"code":"CPSCI 410","title":"Senior Seminar","department":"Computer Science","credits":1,"description":"Practicum in which teams of students provide computer expertise and support for faculty research projects. Topics include software engineering analysis, design, coding, testing, maintenance, and documentation. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/cpsci-computer-science/400/cpsci-410","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":12,"comments":"Open to CPSCI Majors Only","end_time":null,"meetings":[],"start_time":null,"instructors":["Darren J. Strash","Shawn Chen"]}]},
{"code":"CRWR 215","title":"Intro Creative Writg","department":"Creative Writing","credits":1,"description":"Introduction to fundamental techniques of fiction and poetry. Regular writing and reading assignments as well as critiques in class.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/200/crwr-215","sections":[{"days":"TR","room":"225","types":["Proseminar"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"16:00:00","meetings":[{"days":"TR","room":"225","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"225","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Jane E. Springer"]},{"days":"MW","room":"218","types":["Proseminar"],"status":"open","section":"02","building":"List Center","capacity":16,"comments":"Open to 1st Yrs, Soph. & Jrs. Only","end_time":"16:00:00","meetings":[{"days":"MW","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Patrick Joseph Caoile"]}]},
{"code":"CRWR 224","title":"Playwriting","department":"Creative Writing","credits":1,"description":"Introduction to the techniques of realistic and non-realistic playwriting through a variety of exercises and improvisations, culminating in the writing and staging of a one-act play. While no prior acting experience is required, students participate in staged readings of works.","cross_listed":["THETR 224"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/200/crwr-224","sections":[{"days":"TR","room":"219","types":["Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., and Sophomores","end_time":"14:15:00","meetings":[{"days":"TR","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"TR","room":"124","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"219","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Craig T. Latrell"]}]},
{"code":"CRWR 248","title":"Letterpress Studio","department":"Creative Writing","credits":1,"description":"This hands-on practicum in the Dunham Letterpress Studio will teach students the basics of letterpress printing using metal and wood type. The course will focus on setting type, operating presses, layout and design, and gaining knowledge of letterpress printing and book arts through experimentation and practice. Students will develop and produce their own projects, as well as commissioned works for visiting writers and artists. Students with prior experience will practice advanced skills. Group projects will be allowed, subject to instructor approval. There will be selected readings on book history and print culture. May be retaken once for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/200/crwr-248","sections":[{"days":"F","room":"037","types":["Experiential Learning"],"status":"waitlisted","section":"01","building":"Dunham Dormitory","capacity":8,"comments":null,"end_time":"12:00:00","meetings":[{"days":"F","room":"037","type":"LEC","building":"Dunham Dormitory","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Tina M. Hall"]}]},
