{"code":"CRWR 305","title":"Inter Crwr:fiction Workshop","department":"Creative Writing","credits":1,"description":"For students whose work and purpose have developed sufficiently to warrant continuing work in fiction. Regular writing and reading assignments as well as critiques in class.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/300/crwr-305","sections":[{"days":"TR","room":"119","types":[],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores Only","end_time":"12:00:00","meetings":[{"days":"TR","room":"119","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"119","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Patrick Joseph Caoile"]}]},
{"code":"CRWR 309","title":"Creative Non-fict Workshop","department":"Creative Writing","credits":1,"description":"A creative non-fiction workshop in which students will read and discuss essays in some of the following sub-genres: memoir, travel/nature writing, food-writing, and literary journalism by a wide range of authors. Readings will provide models for student work as well as contexts in which to examine the work students generate. Part of our task will be to answer the question: What is creative non-fiction? Through a close examination of the texts we read in class, and the process of both writing and critiquing student essays, we will attempt to clarify the sometimes vague definitions of the genre. Students are encouraged to take CRWR 215 before CRWR 309.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/300/crwr-309","sections":[{"days":"TR","room":"225","types":[],"status":"waitlisted","section":"01","building":"List Center","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores Only","end_time":"12:00:00","meetings":[{"days":"TR","room":"225","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"225","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["T Kira M. Madden"]}]},
{"code":"CRWR 498","title":"Honors Project Crwr","department":"Creative Writing","credits":1,"description":"Independent study under the supervision of creative writing faculty, for honors candidates who wish to qualify for honors in creative writing. Prerequisites, Permission of Department. Students will be assigned to CW faculty for the project.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/crwr-creative-writing/400/crwr-498","sections":[{"days":"W","room":"231","types":[],"status":"waitlisted","section":"01","building":"List Center","capacity":5,"comments":"Open to Senior CRWR majors only.","end_time":"16:00:00","meetings":[{"days":"W","room":"231","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"231","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Anne E. Valente"]},{"days":"W","room":"224","types":[],"status":"open","section":"02","building":"C.A. Johnson Bldg.","capacity":5,"comments":"Open to Senior CRWR majors only.","end_time":"16:00:00","meetings":[{"days":"W","room":"224","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"224","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["T Kira M. Madden"]}]},
{"code":"DANCE 100","title":"Dance Foundations","department":"Dance","credits":1,"description":"An introduction to dance through both practice and theory, exploring dance as a physical, artistic, historical, and cultural form. Students will engage in movement experiences, view and discuss performances, and learn to analyze and interpret dance across multiple genres and traditions. Particular attention is given to situating dance within its historical contexts and tracing how social, political, and cultural forces shape movement practices over time. The course builds foundational skills in movement awareness, critical thinking, and cultural understanding of dance. Open to all students; no previous dance experience required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-100","sections":[{"days":"TR","room":"101","types":[],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"TR","room":"227","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Casey E. Avaunt"]}]},
{"code":"DANCE 112","title":"Elementary Dance","department":"Dance","credits":1,"description":"Studio-based course that introduces students to concepts and techniques of contemporary dance. Emphasizes movement articulation, kinesthetic awareness, and originality. Alongside developing movement fluency, students will learn to analyze and situate contemporary dance within historical and cultural contexts. The course explores how technique reflects cultural values and considers the frameworks through which we understand dancing bodies. No previous dance training required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-112","sections":[{"days":"TR","room":"101","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:45:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Casey E. Avaunt"]}]},
{"code":"DANCE 114","title":"Elementary Ballet","department":"Dance","credits":1,"description":"Beginner-level study of classical ballet with a focus on ballet's basic vocabulary in both barre and center floor exercises, studio-stage directions and designations for the classical positions of the body in space. Work on such stylistic aspects of ballet as musicality, dynamics and use of the head. Readings in kinesiology pertaining to muscular alignment analysis. No previous dance experience required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-114","sections":[{"days":"TR","room":"101","types":[],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":20,"comments":"Open to Srs., Jrs., Soph., & 1st Year.","end_time":"10:15:00","meetings":[{"days":"TR","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Melissa Larish"]}]},
{"code":"DANCE 141","title":"Performance","department":"Dance","credits":0.25,"description":"The study of dance through performance of a role in a main stage dance concert.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Nikolas C. Owens"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Casey E. Avaunt"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Melissa Larish"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Paris Wilcox"]}]},
{"code":"DANCE 159","title":"Elementary Jazz Dance","department":"Dance","credits":1,"description":"An introductory technique course exploring jazz dance as a form grounded in Black American cultural and performance traditions. Students develop foundational skills in rhythm, coordination, and jazz vocabulary while situating studio practice within the historical evolution of jazz dance. Attention is given to stylistic nuance, musicality, and expressive range within jazz movement. Open to all students; no previous dance experience required.","cross_listed":["AFRST 159"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/100/dance-159","sections":[{"days":"MW","room":"101","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs","end_time":"09:45:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Nikolas C. Owens"]}]},
{"code":"DANCE 215","title":"Intermediate Ballet","department":"Dance","credits":1,"description":"Continuation of the study of ballet. Technique classes are combined with studies in kinesiology, dance theory and dance criticism. May be repeated for credit. Prerequisites, 114, or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/200/dance-215","sections":[{"days":"MWF","room":"101","types":[],"status":"open","section":"01","building":"Blood Fitness Center","capacity":25,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"12:15:00","meetings":[{"days":"MWF","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"12:15","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Paris Wilcox"]}]},
{"code":"DANCE 264","title":"Jazz & Black Popular Dance","department":"Dance","credits":1,"description":"Study of the history North American Black vernacular dance forms with a predominant emphasis on jazz dance history as their progenitor. Exploration, investigation, and analysis of social, cultural, and aesthetic concepts and principles prevalent in Black vernacular forms and histories. Study of important and innovative jazz dancers, choreographers, and legacies within the jazz dance continuum. Material engagement modalities will include readings, lectures, discussions, films/video clips, and creative assignments.","cross_listed":["AFRST 264"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/200/dance-264","sections":[{"days":"MW","room":"227","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs","end_time":"15:45:00","meetings":[{"days":"MW","room":"227","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"227","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Nikolas C. Owens"]}]},
{"code":"DANCE 305","title":"Making Dance I","department":"Dance","credits":1,"description":"Provides an introduction to choreographic creation through imagery, improvisation, and embodied exploration. The course emphasizes developing personal movement vocabularies and creative strategies for making dance, with attention to phrasing and structure. Students will experiment with tools including music, costume, props, and basic production elements to create and refine original movement. No prior choreography experience required.","cross_listed":[],"catalog_url":null,"sections":[{"days":"MW","room":"101","types":[],"status":"open","section":"01","building":"Blood Fitness Center","capacity":25,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"Blood Fitness Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"101","type":"FINAL","building":"Blood Fitness Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Nikolas C. Owens"]}]},
{"code":"DANCE 560","title":"Senior Perf.&productn","department":"Dance","credits":1,"description":"A performance of dance works, the choreography of dance works or both. Substantial written component comprising research into the historical, theoretical and socio-cultural contexts of the chosen work. Following submission of the monograph and completion of production, each student will participate in the evaluation of her/his project with an evaluating committee. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/dance-dance-and-movement-studies/500/dance-560","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Open to Seniors only","end_time":null,"meetings":[],"start_time":null,"instructors":["Heather R. Buchman"]}]},
{"code":"DARTS 110","title":"Ways of Seeing","department":"Digital Arts","credits":1,"description":"An introduction to the study of media with a focus on visual media and experience. Students will learn about key moments in media history, from the invention of print to the rise of broadcasting/mass media and the entrenchment of digital/social media. Students will engage with foundational concepts in media and visual studies, and develop tools to critically analyze, discuss, and write about the images that come to us through physical and virtual networks. Topics include: photojournalism, infographics, screen cultures, public relations and advertising, social media, AI, and the effects of digital media on the environment and mental health.","cross_listed":["ARTH 110","CNMS 110"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/100/darts-110","sections":[{"days":"TR","room":"236","types":[],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"236","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"236","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Nadya Bair"]}]},
{"code":"DARTS 113","title":"Intro to Media:integrated Med","department":"Digital Arts","credits":1,"description":"This course will serve as an introduction to digital technology in contemporary art making as it relates to interactivity, collaboration, and emerging practices. Emphasis will be placed on hands on experimentation and exploration across disciplines. We will cover installation art, web art, digital and time-based art, and immersive environments. Students will gain an overview of emerging digital practices, collaborative production strategies and correlations to social, aesthetic and theoretical issues. Other topics may include virtuality, performance, cyborgs, and network culture.","cross_listed":["ART 113","MUSIC 113"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/100/darts-113","sections":[{"days":"R","room":"143","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to 1st Years, Sophomores, and Juniors","end_time":"16:00:00","meetings":[{"days":"R","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"143","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Anna Huff"]}]},
{"code":"DARTS 210","title":"From Cybernetics to AI","department":"Digital Arts","credits":1,"description":"Artificial intelligence and data processing systems shape everyday life, but how did they come about? How did mathematicians, engineers, artists, and designers imagine computer-controlled worlds before they were even possible? And how can their ideas help us raise questions about digital rights, data security, and data justice today? We will explore the media history of data processing and its global transformations through computer art, concrete poetry, experimental media and science fiction films from Germany, Latin America, and the Soviet Union from the 1960s to the present. Our theoretical discussions will be grounded in readings on cybernetics, a theory of communication and control that shaped early computing, but also forged interdisciplinary connections with biology, sociology, literature and art through terms such as \"feedback\" and \"self-regulation.\" This course is specifically aimed at students who want to discover how the sciences and the humanities interact to gain new, creative impulses for their own thinking. Conducted in English; no German required","cross_listed":["GERMN 210"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/200/darts-210","sections":[{"days":"TR","room":"225","types":[],"status":"waitlisted","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"225","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"225","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Lena Truper"]}]},
{"code":"DARTS 221","title":"Intro to Animation","department":"Digital Arts","credits":1,"description":"An introduction to the history, tools and language of basic animation styles. This course will trace the history of experiments in animated imagery from 19th Century photography through 20th Century film into 21st Century digital works. The class will cover basic techniques in Photoshop, Adobe Premier, and illustration and animation software interfaces.","cross_listed":["ART 221"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/200/darts-221","sections":[{"days":"M","room":"144","types":["Cinema and Media Studies"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"M","room":"144","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"144","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Kerry Downey"]}]},
{"code":"DARTS 240","title":"Inter Med:perf, Ritual & Tech","department":"Digital Arts","credits":1,"description":"This class will cover performance strategies in relationship to digital technology, ritual and the social. We will create collaborative and hybrid work at the intersection of performance, digital media and social practice and map out modes of ritual engagement within these intersections. We will explore \"liveness\" as a digital and/or embodied presence and survey contemporary hybrid performance work. Enrollment 16, No prerequisite.","cross_listed":["ART 240","MUSIC 240","THETR 240"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/200/darts-240","sections":[{"days":"R","room":"143","types":["Co-Lab Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years.","end_time":"12:00:00","meetings":[{"days":"R","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Anna Huff"]}]},
{"code":"DARTS 314","title":"Magazines: Digital Approaches","department":"Digital Arts","credits":1,"description":"How can digital tools help us understand print visual culture? This research lab-style seminar integrates humanistic inquiry with a collaborative research and project design process integral to STEM fields. Students will read cutting edge work on illustrated magazines including Life, Vogue, and National Geographic and explore digital humanities projects that offer new ways to explore histories of print media. Students will learn about the possibilities and limits of digital tools such as mapping, network visualizations, and text mining, and design their own projects utilizing digitized collections of illustrated magazines.","cross_listed":["ARTH 314","CNMS 314"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/300/darts-314","sections":[{"days":"T","room":"215","types":["Proseminar"],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":null,"end_time":"16:00:00","meetings":[{"days":"T","room":"215","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"215","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Nadya Bair"]}]},
{"code":"DARTS 319","title":"Adv Media: Tv Club","department":"Digital Arts","credits":1,"description":"This advanced Digital Media class will take place between the Digital Arts Lab, and the Photo/Video studio. The focus will be on live mediated performance broadcasts, and will address histories of public access television, broadcast media, media collectives, social and activist video art, and social implications of a recent return back to livestreaming via the internet. Additional topics covered will include digital and analog tools for live video processing, interactivity and studio audiences, serial TV and internet show formats, green screen techniques, and narrative strategies that utilize the integration of bodies, music, props and media in real time. The course will include weekly internet live streams of student work to the Hamilton community and beyond.","cross_listed":["ART 319","THETR 319"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/darts-digital-arts/300/darts-319","sections":[{"days":"F","room":"143","types":[],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"140","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"143","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Anna Huff","Emily K. Harrison"]}]},
{"code":"DATSC 201","title":"Foundations of Data Science","department":"Data Science","credits":1,"description":"This course focuses on foundational concepts in Data Science. Students are introduced to key mathematical, computational, and statistical principles and how they are applied in modern data science. Topics include data wrangling, the data management lifecycle, core concepts in statistical computing, basic vector and matrix algebra, and an introduction to optimization. Students will apply these concepts to machine learning and statistical analysis through a variety of projects. Additional topics will be covered depending on student interest and instructor expertise.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/datsc-data-science/200/datsc-201","sections":[{"days":"TR","room":"222","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":25,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"222","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"222","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Chinthaka N. Kuruwita"]}]},
{"code":"ECON 100","title":"Introduction to Economics","department":"Economics","credits":1,"description":"The price system as a mechanism for determining which goods will be produced and which inputs employed; decision-making by firms and individuals; market structure; Gross domestic product; its measurement and the determination of production and employment levels; the role of the government in the economy. Not open to seniors.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/100/econ-100","sections":[{"days":"MWF","room":"102","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to 1st Years, Sophomores & Juniors Only Not open to those who took Econ 101 & 102","end_time":"09:50:00","meetings":[{"days":"MWF","room":"102","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"T","room":"125","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Cody A. Couture"]},{"days":"MWF","room":"102","types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to 1st Years, Sophomores & Juniors Only Not open to those who took Econ 101 & 102","end_time":"10:50:00","meetings":[{"days":"MWF","room":"102","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"T","room":"125","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Cody A. Couture"]},{"days":"MWF","room":"101","types":["Quantitative & Symbolic R"]