{"code":"ECON 522","title":"Gender & LGBTQ Ec Sr Project","department":"Economics","credits":1,"description":"This course examines the causes and consequences of gender and sexual orientation differences in economic outcomes such as education, labor supply, marriage, household, and family choices. This class satisfies the senior project requirement through an empirical study closely related to a topic covered in the Topics in Economics of Gender and Sexual Orientation.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/500/econ-522","sections":[{"days":"MW","room":"202","types":["Senior Project"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"202","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"202","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Evelyn E. Skoy"]}]},
