{"code":"ECON 539","title":"Sr Proj Sustain Econ Growth","department":"Economics","credits":1,"description":"A senior project for concentrators in the department. Students will work on projects related to sustainability, environmental policy, and economic growth.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/500/econ-539","sections":[{"days":"TR","room":"110","types":[],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Hannah Rhodenhiser"]}]},
{"code":"ECON 560","title":"Research Seminar","department":"Economics","credits":1,"description":"Each student works intensively on a topic chosen in consultation with the instructor. Weekly meetings held to hear progress reports and to discuss research techniques pertinent to student topics. Candidates for honors must complete this course.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/econ-economics/500/econ-560","sections":[{"days":"MW","room":"103","types":["Senior Project"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":6,"comments":"Instructor's Signature Req. Open to Seniors Only. Restricted to Econ Concentrators","end_time":"09:45:00","meetings":[{"days":"MW","room":"103","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"103","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Evelyn E. Skoy"]},{"days":"MW","room":"109","types":["Senior Project"],"status":"waitlisted","section":"02","building":"Kirner-Johnson Building","capacity":6,"comments":"Instructor's Signature Req. Open to Seniors Only. Restricted to Econ Concentrators","end_time":"09:45:00","meetings":[{"days":"MW","room":"109","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"109","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Stephen Wu"]}]},
{"code":"EDUC 102","title":"Issues in Education","department":"Education","credits":1,"description":"What is education? What is school? How do we critically understand education and schools? What are the possibilities and limitations of education for change and justice? Emphasis on, but not limited to, American education. Includes lecture, discussion, multi-media projects, and small-group interaction.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/educ-education-studies/100/educ-102","sections":[{"days":"WF","room":"250","types":[],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to 1st Years, Sophomores & Juniors Only","end_time":"14:15:00","meetings":[{"days":"WF","room":"250","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"250","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Chenyu Wang"]}]},
{"code":"EDUC 207W","title":"The University","department":"Education","credits":1,"description":"Just what is a university, understood anthropologically? How do we understand its many subcultures, its organizational forms, its economies and its ideological functions? In this course, we will critically examine these questions, and discuss how \"the university\" is shaped by forces of globalization, migration, neoliberalism, and discourses of diversity. We will read ethnographies about \"the university\", analyzing how \"the university,\" as a cultured institution, produces and reproduces various forms of inequality as well as generates new forms of subjectivity. May be taught as an FYC at the discretion of the department. No prerequisites when taught as an FYC.","cross_listed":["ANTHR 207W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/educ-education-studies/200/educ-207","sections":[{"days":"WF","room":"250","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":"Open to First-Years Only. (FYC)","end_time":"15:45:00","meetings":[{"days":"WF","room":"250","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"250","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Chenyu Wang"]}]},
{"code":"EDUC 224","title":"Knowledge & Education","department":"Education","credits":1,"description":"A survey of fundamental concepts in education through historical and contemporary texts. We start by thinking about the goals of education, including knowledge, virtue, and skills. Next, we consider human capacities for learning before turning to the nature of learning and various approaches to teaching. Finally, we look at the relation between schools and society and consider how to design more effective institutions for learning. Knowledge and Education is a team-based learning class. Not open to students who have completed Philosophy 124: Philosophy of Education.","cross_listed":["PHIL 224"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/educ-education-studies/200/educ-224","sections":[{"days":"TR","room":"236","types":[],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Not open to those who took PHIL 124.","end_time":"10:15:00","meetings":[{"days":"TR","room":"236","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"236","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Russell S. Marcus"]}]},
{"code":"EDUC 264W","title":"Ethnogrphy Lit&visual Lang","department":"Education","credits":1,"description":"Theory and analysis of communication and meaning in social and cultural context with particular attention devoted to the often-neglected aspects of literate communication.","cross_listed":["ANTHR 264W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/educ-education-studies/200/educ-264","sections":[{"days":"WF","room":"127","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":"127","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"127","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Chaise Ladousa"]}]},
{"code":"EDUC 329","title":"Globalization and Education","department":"Education","credits":1,"description":"While human communities have always been connected to one another in important ways, recent history has seen a quickening of transportation and communication, increasing the circulation of people, objects, and forms across significant distances. What are the effects of such circulation, for whom, and in what geographies? How does such circulation shaped education around the world? We will examine several \"problem-spaces\" relevant to the study of education, such as globalization and race, immigration, global testing and assessment regimes, education and human rights, etc.","cross_listed":["ANTHR 329"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/educ-education-studies/300/educ-329","sections":[{"days":"R","room":"142","types":[],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"R","room":"142","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"142","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Chenyu Wang"]}]},
{"code":"EDUC 395N","title":"Intensive Special Needs Teach","department":"Education","credits":2,"description":"Each student is assigned full-time teaching responsibilities, under supervision, in a setting with learners with intensive special needs. Includes extensive practicum experience with a focus on teaching and case management. Papers and attendance at weekly seminars required. Course available to students enrolled in the cooperative program at the New England Center for Children; earns two course credits with only one course credit counting toward requirements for the minor in education studies. Evaluated Satisfactory/Unsatisfactory.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"ENVST 110","title":"Intro to Environmental Studie","department":"Environmental Studies","credits":1,"description":"This course presents the core literature, theories, and concepts in environmental studies, with a focus on the emerging discipline of sustainability science. It will provide a comprehensive foundation for interdisciplinary study of contemporary environmental issues that will prepare students for more advanced work on the biophysical, social and human dimensions of environmental problems, including problems at the food-energy-water-climate nexus. This course is a required component of the Environmental Studies concentration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/100/envst-110","sections":[{"days":"MW","room":"G041","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to 1st Years and Sophomores Only","end_time":"14:15:00","meetings":[{"days":"MW","room":"G041","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"G041","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Heather A. Kropp"]},{"days":"TR","room":"G041","types":[],"status":"waitlisted","section":"02","building":"Taylor Science Center","capacity":40,"comments":"Open to 1st Years and Sophomores Only","end_time":"11:45:00","meetings":[{"days":"TR","room":"G041","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"G041","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Aalayna R. Green"]}]},
{"code":"ENVST 206","title":"Intro to Environmental Data","department":"Environmental Studies","credits":1,"description":"This course examines the potential for big data to address major environmental issues related to climate change, conservation, and water security. We gain a critical understanding of the role of satellites, environmental sensors, and citizen science in describing the environment. Topics will include data life cycles, statistics, visualization, and statistical programming for environmental data.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-206","sections":[{"days":"MWF","room":"236","types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":20,"comments":"Open to Seniors, Juniors, Sophomores Only. Not open to students who have taken MATH 152, MATH 254, or ECON 166.","end_time":"10:50:00","meetings":[{"days":"MWF","room":"236","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"236","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Heather A. Kropp"]}]},
{"code":"ENVST 212","title":"Climate Change","department":"Environmental Studies","credits":1,"description":"This course investigates the scientific, social, economic and political dimensions of anthropogenic climate change, including our scientific understanding of its causes, its local and planetary human and ecological impacts, and the potential for technological, social and policy solutions. Throughout the course, we critically examine the roles of public policy and international negotiations in developing equitable mitigation and adaptation strategies to combat the totalizing problem of our times.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-212","sections":[{"days":"MW","room":"3024","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Seniors, Juniors, & Sophomores","end_time":"14:15:00","meetings":[{"days":"MW","room":"3024","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"3024","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Aaron L. Strong"]}]},
{"code":"ENVST 234","title":"Environmental Justice","department":"Environmental Studies","credits":1,"description":"This interdisciplinary seminar examines environmental justice as a movement and concept. We interrogate and discuss the historical role of racism, heteropatriarchy, colonialism and globalization in (re)producing and justifying place-based environmental contamination and toxicity. Through close analysis of case studies in the US and the Global South, students analyze and present on how disenfranchised groups have made political demands, scaled up, forged solidarities, asserted climate justice, challenged state and corporate projects and conducted citizen science in rural and urban settings.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-234","sections":[{"days":"TR","room":"236","types":["Proseminar","Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Seniors, Juniors, & Sophomores Only","end_time":"15:45:00","meetings":[{"days":"TR","room":"236","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"236","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Aalayna R. Green"]}]},
{"code":"ENVST 265","title":"Indigenous North American Lit","department":"Environmental Studies","credits":1,"description":"This course will focus on contemporary literature, film, poetry, and creative nonfiction written by North American Indigenous authors from various nations within both the United States and Canada with attention to colony and empire, climate change, sovereignty, emergent indigeneity, and multispecies kinship. As much as possible, we will place these texts within their historical, culturally-specific, and national contexts, as well as in relation to each other and to ourselves in our classroom at Hamilton. Texts may include works by Louise Erdrich, N. Scott Momaday, Leslie Marmon Silko, Robin Wall Kimmerer, Leanne Simpson, Rebecca Nagle, Lisa Jackson, Stephen Graham Jones, Thomas King, Tommy Pico, Cherie Dimaline, and Danis Goulet.","cross_listed":["LIT 265"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-265","sections":[{"days":"TR","room":"3021","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:45:00","meetings":[{"days":"TR","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Brianna R. Burke"]}]},
{"code":"ENVST 266","title":"Global Environmental History","department":"Environmental Studies","credits":1,"description":"A survey of topics, themes, and methods in environmental history, focusing on Africa, Asia, and Latin America. Provides a foundation and prepare students for advanced coursework and research in history and environmental studies. Examines major events and trends through an environmental framework, illustrating connections over time. Major course themes include biological exchange between regions, the industrial revolution, climate change, and linking historical environmental issues to contemporary concerns.","cross_listed":["HIST 266"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-266","sections":[{"days":"WF","room":"101","types":["Environmental Studies"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"15:45:00","meetings":[{"days":"WF","room":"101","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"101","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Chao Ren"]}]},
{"code":"ENVST 269","title":"Climate Fiction & Film","department":"Environmental Studies","credits":1,"description":"In this course, we will examine how fiction and film about the climate crisis document our anxieties, remediate our ecologies, and reimagine our climate futures. Students will be introduced to Ecocriticism and the Environmental Humanities while reading and watching across subgenres; a portion of the course will include American Indian and First Nations texts. Course materials will include contemporary novels, short stories, film, media, and theory. Our class screenings and discussions will be supplemented by visits from writers and filmmakers thinking through the social, ethical, and political implications of making media about the climate crisis.","cross_listed":["LIT 269"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-269","sections":[{"days":"TR","room":"3021","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Srs, Jrs, and Sophomores","end_time":"10:15:00","meetings":[{"days":"TR","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Brianna R. Burke"]}]},
{"code":"ENVST 291","title":"Environmental Studies Resear","department":"Environmental Studies","credits":0.25,"description":"Independent research under the supervision of a faculty member in environmental studies. May be repeated for credit. One-quarter, one-half or one credit per semester. Open to all class years. For seniors, independent research projects should not be on the same topic as their senior thesis or capstone projects. Instructor's permission required.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/200/envst-291","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Aaron L. Strong"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Heather A. Kropp"]}]},
{"code":"ENVST 360W","title":"Pol&theory Place & Space","department":"Environmental Studies","credits":1,"description":"How do we map out, conceptualize, inhabit and govern our spatial environment? What political challenges arise in organizing and maintaining a coherent world of places? A look at the theoretical and political dimensions of place and space through writings of geographers, political theorists, environmental thinkers, novelists and U.S. case studies, including 9/11, the debate over logging in the Pacific Northwest, the problem of sprawl, the decline and revival of old industrial cities, the future of America's agricultural landscape, and the impact of climate change. (Political Theory)","cross_listed":["GOVT 360W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/300/envst-360","sections":[{"days":"WF","room":"110","types":["Environmental Studies","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":"Open to Seniors, Juniors, & Sophomores Only","end_time":"15:45:00","meetings":[{"days":"WF","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Peter F. Cannavo"]}]},
{"code":"ENVST 549","title":"Prep Research Senior Project","department":"Environmental Studies","credits":0.5,"description":"Students doing experiments, data-gathering, or other significant empirical or field work in preparation for their senior project should carry out this work prior to taking 550 and under the guidance of their thesis adviser. This research course is generally done in the fall of senior year, but in certain circumstances may be completed in the spring of junior year or the summer before senior year. Depending on the extent of their research, students may take this course for full or half credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/envst-environmental-studies/500/envst-549","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Peter F. Cannavo"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Aaron L. Strong"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's Signature Req.","end_time":null,"meetings":[],"start_time":null,"instructors":["Pete Guiden"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Andrea K. Townsend"]},{"days":null,"room":null,"types":[],"status":"open","section":"05","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Heather A. Kropp"]},{"days":null,"room":null,"types":[],"status":"open","section":"06","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Peter F. Cannavo"]}]},
{"code":"FRNCH 110","title":"Elementary French","department":"French","credits":1,"description":"A thorough grounding in speaking, writing, reading and comprehension for beginners. This is an intensive, interactive course in which students make rapid gains in oral fluency and are able to read short texts. Textbook readings, daily on-line and written exercises supplemented by short texts and films. For students with no prior experience in French. Four hours of class, plus one session with a teaching assistant. First-Year students who follow the sequence through FRNCH 140 may qualify for Hamilton in France, with consent of the director.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/100/frnch-110","sections":[{"days":"MWF","room":"207","types":["Proseminar"],"status":"open","section":"01","building":"Couper Hall","capacity":16,"comments":"Open to Srs,., Jrs., Soph., & 1st Yrs","end_time":"10:50:00","meetings":[{"days":"MWF","room":"207","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"T","room":"305","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Zachary Desjardins-Mooney"]},{"days":"MWF","room":"207","types":["Proseminar"],"status":"open","section":"02","building":"Couper Hall","capacity":16,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"207","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"305","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"11:00:00","instructors":["Zachary Desjardins-Mooney"]}]},
{"code":"FRNCH 130","title":"Intermediate French I","department":"French","credits":1,"description":"The diversity of the French-speaking world provides the focus for active student engagement toward the acquisition of greater proficiency in speaking, comprehending, reading, and writing French. Reinforcement of major grammatical structures, regular oral practice and conversation, readings in contemporary cultures and social issues. Incorporates texts, film, and other media as the basis for discussion, debate, exposés, and short compositions. Three hours of class and session with teaching assistant.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/100/frnch-130","sections":[{"days":"MWF","room":"209","types":["Proseminar"],"status":"open","section":"01","building":"Root Hall","capacity":16,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs","end_time":"11:50:00","meetings":[{"days":"MWF","room":"209","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"209","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Joseph E. Mwantuali"]}]},
{"code":"FRNCH 140","title":"Intermediate French II","department":"French","credits":1,"description":"This intermediate-level French course is based on film scripts, films, and other related materials. Focus on speaking, listening, reading, and writing to express ideas and arguments with precision and nuance. Review of advanced grammar structures and expansion of vocabulary to develop strategies for description and narration and in expressing preferences and opinions, Analysis of texts and films develops critical thinking in French. Activities such as debate, interviews, discussion, and written assignments. Conducted entirely in French.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/100/frnch-140","sections":[{"days":"MWF","room":"210","types":["Proseminar"],"status":"open","section":"01","building":"Root Hall","capacity":16,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs","end_time":"11:50:00","meetings":[{"days":"MWF","room":"210","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"210","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Claire Frances"]}]},
{"code":"FRNCH 200W","title":"Written & Oral Argumentatn","department":"French","credits":1,"description":"An intensive course focusing on oral and written argumentation, proper nuanced expression, improvement of syntax and vocabulary-building strategies through the exploration of contemporary literary and cultural texts. Heritage speakers with instructor permission. Regular class meetings plus a weekly discussion session with a teaching assistant.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/200/frnch-200","sections":[{"days":"TR","room":"250","types":["Cultural Diversity Course","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"11:45:00","meetings":[{"days":"TR","room":"250","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"250","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:30:00","instructors":["Paule Carbonnel"]}]},
{"code":"FRNCH 211","title":"Education in Literature","department":"French","credits":1,"description":"This course explores the various representations of education in French and Francophone literatures, from the 17th to the 21st century. Texts written about academic, social, individual, and familial education are studied in conjunction with historic and geographical considerations of gender roles, along with national and colonial history. Reading across genres (theater, pamphlets, novel, autobiography, and autofiction) and across historical periods, we will learn how to think and write critically about literature in its cultural contexts using various techniques and methodologies of textual analysis. Authors include Molière, Rousseau, Colette, Pennac, Sijie, and Bouraoui. (Proseminar.) Topics vary, may be retaken for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/200/frnch-211","sections":[{"days":"TR","room":"224","types":["Proseminar"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"15:45:00","meetings":[{"days":"TR","room":"224","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"224","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Zachary Desjardins-Mooney"]}]},
{"code":"FRNCH 280","title":"Francophone Cultures","department":"French","credits":1,"description":"An introduction to cultures of French-speaking areas beyond the Hexagon: Africa, the Caribbean, Canada. Topics include the history of slavery, colonization and neo-colonization; literatures; sculptures, masks, paintings; fashion; and cuisines. Discussion based on readings, films and presentations by native informants.Taught in French. Instructor's consent required for those returning from study in France.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/200/frnch-280","sections":[{"days":"MW","room":"210","types":["Cultural Diversity Course","Proseminar","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Root Hall","capacity":16,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"15:45:00","meetings":[{"days":"MW","room":"210","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"210","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Joseph E. Mwantuali"]}]},
{"code":"FRNCH 363","title":"Speculative Futures in French","department":"French","credits":1,"description":"From Jules Verne's Extraordinary Voyages to twenty-first-century \"cli-fi,\" this course traces the development and significance of French and Francophone speculative fiction, exploring how speculative narratives have imagined - and interrogated - technological change, scientific discovery, environmental transformation, and social change. Focusing on the nineteenth century, a period of rapid scientific and industrial change, we analyze how the era's unique debates and anxieties resonate in contemporary speculative writing, from climate fiction to Afrofuturism. Authors may include Verne, Flammarion, Boulle, Vonarburg, Nsafou, and Roch, alongside scientific and philosophical texts. Students will develop their own speculative fiction project in French. Course may include mandatory field trip.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/300/frnch-363","sections":[{"days":"MW","room":"210","types":["Speaking Intensive Course"],"status":"open","section":"01","building":"Root Hall","capacity":16,"comments":"Open to Srs., Jrs. & Sophomores","end_time":"14:15:00","meetings":[{"days":"MW","room":"210","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"210","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Paule Carbonnel"]}]},
{"code":"FRNCH 455","title":"The African Novel","department":"French","credits":1,"description":"Critical examination of the novel's evolution from the colonial period through independence and on to post-colonial writings. The search for authenticity and answers to problems of narrative techniques, oral and written traditions, African feminism, politics, cultures, and the role of the writer. Authors include Lomani Tshibamba, Sembene Ousmane, Nafissatou Diallo, Aoua Kita, Daniel Biyaoula, Ahmadou Kourouma, Henri Lopes, Calixthe Beyala, Aminata Sow Fall, Ken Bugul, Mariama B, and Werewere Liking. Taught in French. Prerequisites, 300-level course; or instructor's permission.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/frnch-french-and-francophone-studies/400/frnch-455","sections":[{"days":"TR","room":"206","types":["Cultural Diversity Course"],"status":"waitlisted","section":"01","building":"Root Hall","capacity":12,"comments":"Open to Senior French Concentrators and Minors Only","end_time":"11:45:00","meetings":[{"days":"TR","room":"206","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"206","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Joseph E. Mwantuali"]}]},
{"code":"GEARC 325W","title":"Analytic Methods Arch","department":"Geoarchaeology","credits":1,"description":"A survey of analytic techniques central to archaeological and paleoecological interpretation. Laboratory performance of artifact analysis and classification, computer-aided data management and statistical analysis. Three hours of class and three hours of laboratory.","cross_listed":["ARCH 325W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/gearc-geoarchaeology/300/gearc-325","sections":[{"days":"M","room":"2012","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":8,"comments":null,"end_time":"16:00:00","meetings":[{"days":"M","room":"2012","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"2012","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"2012","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Eric Hubbard"]}]},
{"code":"GEOSC 107","title":"Global Geo & Env Challenges","department":"Geosciences","credits":1,"description":"This course will explore a variety of geological and environmental challenges faced by people around the world. We will investigate the causes of these challenges and compare how they are being confronted by different populations around the world. Examples of topics to be explored include how humans are trying to mitigate and prepare for climate change, threats to drinking water quality and quantity (contamination, droughts), conflicts surrounding natural resource extraction (oil, economic minerals), and risks posed by geologic hazards (landslides, earthquakes, volcanoes). Throughout the course we will use data and science-based evidence to determine the causes of the challenges, propose potential solutions, and assess whether ongoing and proposed solutions are likely to succeed.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/100/geosc-107","sections":[{"days":"MWF","room":"1030","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":"Open to First Years and Sophomores only","end_time":"10:50:00","meetings":[{"days":"MWF","room":"1030","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"1030","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"15:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"1030","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Sarah Jonathan"]}]},
{"code":"GEOSC 117","title":"Earth Through Time","department":"Geosciences","credits":1,"description":"Earth has been a continuously operating - and continuously changing - system for over 4.5 billion years. This course will explore fundamental concepts in geoscience through the lens of changes in the Earth system over geologic time. Topics include the formation of Earth and the solar system, plate tectonics, the evolution of life, natural hazards (including earthquakes and volcanoes), and Earth's climate. Three hours of class and two hours of laboratory with required field trip(s). Not open to students who have taken any other course in Principles of Geoscience.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/100/geosc-117","sections":[{"days":"MWF","room":"1033","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":"Open to 1st Yrs and Sophomores Only","end_time":"11:50:00","meetings":[{"days":"MWF","room":"1033","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"M","room":"1033","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"15:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"T","room":"1033","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Amy Moser"]}]},
{"code":"GEOSC 211","title":"Paleoenvironments","department":"Geosciences","credits":1,"description":"This course focused on how the fundamentals of sedimentology and stratigraphy can be used to reconstruct past environments and study how they change through time. This will include a study of the classification of siliciclastic and carbonate rocks, how the energy of systems controls the type of rocks deposited, and the paleoclimatic/tectonic significance of depositional sequences. Three hours of class and three hours of laboratory with field trips.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-211","sections":[{"days":"MWF","room":"1035","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"1035","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"M","room":"1035","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"T","room":"1035","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Catherine Beck"]}]},
{"code":"GEOSC 233","title":"Plate Tectonics","department":"Geosciences","credits":1,"description":"The discovery of Plate Tectonics is one of the great scientific revolutions of the 20th century. This course is a deep dive into the foundational observations and the remarkable ingenuity that led to a complete rethinking of the way our planet works and unlocked a new era of scientific discovery. Throughout the course, students will compare early seminal observations with modern datasets to gain an understanding of the current state of knowledge and the scientific questions that still remain unresolved. Students will learn to analyze a wide array of interdisciplinary data, including paleontological, geophysical, and geochemical datasets. The course will include selected historical readings, primary literature, problem sets and a final project.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-233","sections":[{"days":"TR","room":"1016","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"1016","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"1016","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Nicolas M. Roberts"]}]},
{"code":"GEOSC 250","title":"Sem Geology of Desert Sw","department":"Geosciences","credits":0.5,"description":"This is a half-credit seminar to prepare students for GEOSC 291 (Field Studies in the Desert Southwest). Students will meet for 3 hours every other week to learn about the geologic and human history of the southwestern United States, with an emphasis on the large-scale geologic processes that shaped Arizona and how humans interact with, and modify, the natural environment. Students must co-enroll in GEOSC 291.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-250","sections":[{"days":"T","room":"1016","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":20,"comments":"Students must co-enroll in GEOSC-291","end_time":"16:00:00","meetings":[{"days":"T","room":"1016","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"1016","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Nicolas M. Roberts"]}]},
{"code":"GEOSC 290","title":"Paleontology","department":"Geosciences","credits":1,"description":"A study of the history of life, evolution and the fossil record. Topics include the general principles of paleontology, nomenclature, taxonomy, identification techniques, fossilization processes, plants, microfossils, invertebrates and vertebrates. Three hours of class and three hours of laboratory with field trips.","cross_listed":["BIO 290"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-290","sections":[{"days":"MWF","room":"1011","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":"Open to Seniors, Juniors, & Sophomores","end_time":"10:50:00","meetings":[{"days":"MWF","room":"1011","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"1011","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"1011","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Kristopher M. Kusnerik"]}]},
{"code":"GEOSC 291","title":"Field Studies in Desert Sw","department":"Geosciences","credits":0.5,"description":"A field study of the geology of southern and central Arizona. Emphasis will be placed on examining evidence of large-scale geologic processes and how humans interact with, are influenced by, and modify the natural environment. A 10-day, intensive field course emphasizing experiential learning. Course will involve moderate hiking in remote areas. Students must co-enroll in GEOSC 250.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-291","sections":[{"days":null,"room":null,"types":[],"status":"waitlisted","section":"01","building":null,"capacity":20,"comments":"Two week trip occuring January 2-14, 2025 (Tentatively)","end_time":null,"meetings":[],"start_time":null,"instructors":["Nicolas M. Roberts"]}]},
{"code":"GEOSC 298","title":"Geoscience Research","department":"Geosciences","credits":0.25,"description":"Geoscience research under the supervision of a faculty member. May be repeated for credit. Students may count up to 1 credit of geoscience research toward the concentration. One quarter, one half, or one credit per semester. No senior concentrators.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/200/geosc-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Kristopher M. Kusnerik"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nicolas M. Roberts"]}]},
{"code":"GEOSC 313","title":"Geochronology","department":"Geosciences","credits":1,"description":"Constraining the absolute timing of events throughout Earth history is critical for fully describing Earth as a system. In this course, students will be introduced to the various isotopic systems, datasets, and methods that geoscientists use in geochronology studies. We will explore the fundamental science that governs these techniques, as well as their applications to a wide-range of geoscience processes, including tectonics, environment and landscape evolution, and Earth's climate.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/300/geosc-313","sections":[{"days":"MW","room":"1033","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":24,"comments":null,"end_time":"09:45:00","meetings":[{"days":"MW","room":"1033","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"1033","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Amy Moser"]}]},
{"code":"GEOSC 510","title":"Senior Project","department":"Geosciences","credits":0.5,"description":"A two-term course during which concentrators pursue an independent research project and present the results to the department. Proposals for independent research projects must be completed in the spring semester of the student's junior year. Must be taken in conjunction with the Department's two-term, Senior Seminar (GEOSC 551 / 552). Both courses are required for the concentration. One-half course credit each for 510 and 511.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Amy Moser"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Kristopher M. Kusnerik"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Nicolas M. Roberts"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"05","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Catherine Beck"]}]},
{"code":"GEOSC 551","title":"Senior Seminar I","department":"Geosciences","credits":0.5,"description":"A half-credit seminar to be taken in conjunction with GEOSC 510 (Senior Project). In this course students will examine, discuss, and reflect upon structural and institutional hierarchies in the geosciences based on the social categories of race, class, gender, ethnicity, nationality, religion, sexuality, age, and/or disabilities. Students will also discuss ethical issues related to work and behavior as geoscience professionals. This seminar, taken along with its companion spring semester seminar (GEOSC-552) will satisfy the department's SSIH requirement.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/geosc-geosciences/510500/geosc-551","sections":[{"days":"R","room":"1011","types":["Senior Project","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to GEOSC/GEARCH Seniors only","end_time":"16:00:00","meetings":[{"days":"R","room":"1011","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"14:30"}],"start_time":"14:30:00","instructors":["Kristopher M. Kusnerik"]}]},
{"code":"GERMN 110","title":"First Term German","department":"German","credits":1,"description":"Introduction to the German language. Exercises in aural comprehension, speaking, reading and writing reinforced by short cultural and literary texts. No previous knowledge of German required. Four hours of class, with additional drill sessions and laboratory work.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/100/germn-110","sections":[{"days":"MWRF","room":"224","types":[],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":16,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWRF","room":"224","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"}],"start_time":"10:00:00","instructors":["Franziska Schweiger"]}]},
{"code":"GERMN 130","title":"Third Term German","department":"German","credits":1,"description":"Review of grammar, syntax and conversational techniques through work in aural comprehension, speaking, reading and writing. Literary texts supplemented with realia (such as news stories German songs, videos). Three hours of class.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/100/germn-130","sections":[{"days":"MWF","room":"111","types":[],"status":"open","section":"01","building":"Couper Hall","capacity":16,"comments":null,"end_time":"13:50:00","meetings":[{"days":"MWF","room":"111","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"111","type":"FINAL","building":"Couper Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Franziska Schweiger"]}]},
{"code":"GERMN 200W","title":"Topics German Lang. & Lit.","department":"German","credits":1,"description":"Close reading of short texts and newspaper articles; advanced grammar review and extensive writing exercises. Readings focus on contemporary Germany and Austria. Designed for students who have had two years of German or equivalent. Taught in German. Prerequisites, 140 or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/200/germn-200","sections":[{"days":"TR","room":"309","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":"309","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"309","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Franziska Schweiger","Lena Truper"]}]},
{"code":"GERMN 210","title":"From Cybernetics to AI","department":"German","credits":1,"description":"Artificial intelligence and data processing systems shape everyday life, but how did they come about? How did mathematicians, engineers, artists, and designers imagine computer-controlled worlds before they were even possible? And how can their ideas help us raise questions about digital rights, data security, and data justice today? We will explore the media history of data processing and its global transformations through computer art, concrete poetry, experimental media and science fiction films from Germany, Latin America, and the Soviet Union from the 1960s to the present. Our theoretical discussions will be grounded in readings on cybernetics, a theory of communication and control that shaped early computing, but also forged interdisciplinary connections with biology, sociology, literature and art through terms such as \"feedback\" and \"self-regulation.\" This course is specifically aimed at students who want to discover how the sciences and the humanities interact to gain new, creative impulses for their own thinking. Conducted in English; no German required","cross_listed":["DARTS 210"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/200/germn-210","sections":[{"days":"TR","room":"225","types":[],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"225","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"225","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Lena Truper"]}]},
{"code":"GERMN 298","title":"Adv Language & Culture","department":"German","credits":0.25,"description":"1/4-credit class that must be taken in conjunction with a course in English. Additional weekly session to analyze and discuss the material in the original language. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/200/germn-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":10,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Franziska Schweiger"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Lena Truper"]}]},
{"code":"GERMN 440","title":"Modern Lit Germn Countries","department":"German","credits":1,"description":"Study of post-1945 literature with focus on Austria, the emergence of two contrasting Germanies, and the Neuanschluss leading to unification. Texts by Bachmann, Bernhard, Bll, Grass, Seghers, Wolf and others. Taught in German. Prerequisites, 310 or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/germn-german-studies/400/germn-440","sections":[{"days":"MW","room":"309","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"309","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"309","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Franziska Schweiger"]}]},
{"code":"GOVT 112W","title":"Comparative Politics","department":"Government","credits":1,"description":"Introduction to the study of non-American national political systems, emphasizing authority, legitimacy and processes of state- and nation-building. Comparison of alternate forms of political development in selected Western and non-Western countries. (Proseminar and writing-intensive in the Fall.) (Comparative Politics)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/govt-government/100/govt-112","sections":[{"days":"WF","room":"142","types":["Cultural Diversity Course","Proseminar","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to First Years and Sophomores","end_time":"14:15:00","meetings":[{"days":"WF","room":"142","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"142","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Lindsey Pruett"]},{"days":"WF","room":"142","types":["Cultural Diversity Course","Proseminar","Writing Intensive Courses"],"status":"waitlisted","section":"02","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to First Years and Sophomores","end_time":"15:45:00","meetings":[{"days":"WF","room":"142","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"142","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Lindsey Pruett"]}]},
