{"code":"JAPN 130","title":"Third Term Japanese","department":"Japanese","credits":1,"description":"Completion of introduction to basic structures of the language. Continued emphasis on oral communication, with practice in reading simple texts. An additional 104 kanji characters will be introduced. Four 50-minute classes a week (Monday-Thursday). Prerequisites, 120 or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/japn-japanese/100/japn-130","sections":[{"days":"MW","room":"211","types":[],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MW","room":"211","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"TR","room":"211","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"10:20","start_date":"2026-08-27","start_time":"09:30"},{"days":"T","room":"211","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Haruka Higa"]}]},
{"code":"JAPN 200","title":"Advanced Japanese I","department":"Japanese","credits":1,"description":"Increasing emphasis on written Japanese, with acquisition of an additional 160 kanji characters.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/japn-japanese/200/japn-200","sections":[{"days":"MWF","room":"215","types":[],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"215","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"T","room":"215","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Kyoko Omori"]}]},
{"code":"JAPN 239","title":"Japan:a-bomb to Dragon Ball Z","department":"Japanese","credits":1,"description":"This course delves into the complexities of modern Japan, placing a particular emphasis on pivotal topics such as military conflicts, the pursuit of pacifism, the experience of nuclear victimhood, periods of foreign occupation, and the concept of social responsibility. To achieve a deeper understanding of these themes and to appreciate their varied representations, we employ a multifaceted approach. Our exploration encompasses a range of media forms, including films, radio broadcasts, literary works, and digital archives. Additionally, we will delve into a diverse array of genres, spanning from documentary and war propaganda to personal storytelling. Through these diverse lenses, we aim to cultivate a more nuanced and multifaceted understanding of these historical narratives. Taught in English. No knowledge of Japanese language or history required.","cross_listed":["CNMS 239","LIT 239"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/japn-japanese/200/japn-239","sections":[{"days":"WF","room":"207","types":["Asian Studies","Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Benedict Hall","capacity":20,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Kyoko Omori"]}]},
{"code":"JAPN 401","title":"Readings in Japanese","department":"Japanese","credits":1,"description":"Reading in modern literary and non-literary texts and mastery of the remaining kanji characters on the joyo kanji list. Through advanced-level reading of original texts and in-depth discussion, students focus on topics such as Japanese literature, film, culture and linguistics. This course also accommodates and guides senior theses. Prerequisites, 220, or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/japn-japanese/400/japn-401","sections":[{"days":"MF","room":"215","types":["Cultural Diversity Course","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":null,"end_time":"09:45:00","meetings":[{"days":"MF","room":"215","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"215","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Kyoko Omori"]}]},
{"code":"JWST 111W","title":"Ancient Jewish Wisdom","department":"Jewish Studies","credits":1,"description":"An Introduction to the Jewish Tradition and Jewish way of reading.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/jwst-jewish-studies/100/jwst-111","sections":[{"days":"TR","room":"207","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Couper Hall","capacity":18,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"207","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"207","type":"FINAL","building":"Couper Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Benjamin Steiner"]}]},
{"code":"JWST 219","title":"American Jewish History","department":"Jewish Studies","credits":1,"description":"This course covers significant themes and developments in American Jewish life from the colonial period to the present. Together, we will focus on historic Jewish social, political, religious, and cultural patterns and how they account for the character of American Jewish life today. We will also explore the evolving relationship between Jews and American culture. Finally, we will engage with important historiographic debates in the field of American Jewish Studies. Careful examination of primary sources will further each of these classroom goals.","cross_listed":["HIST 219"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/jwst-jewish-studies/200/jwst-219","sections":[{"days":"TR","room":"205","types":[],"status":"open","section":"01","building":"Root Hall","capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":"205","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"205","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Benjamin Steiner"]}]},
{"code":"LATIN 110","title":"Elementary Latin I","department":"Latin","credits":1,"description":"An introduction to the language and culture of ancient Rome. Thorough grounding in Latin grammar, syntax and vocabulary. Reading and discussion of elementary passages that cast light on the society and culture of ancient Rome and its empire. No knowledge of Latin required. Three class meetings a week, in addition to a drill session.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/latin-latin/100/latin-110","sections":[{"days":"MWF","room":"110","types":["Proseminar"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"11:50:00","meetings":[{"days":"MWF","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Jesse D. Weiner"]},{"days":"MWF","room":"110","types":["Proseminar"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"12:50:00","meetings":[{"days":"MWF","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"},{"days":"M","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"12:00:00","instructors":["Jesse D. Weiner"]}]},
{"code":"LATIN 210","title":"Intermediate Latin","department":"Latin","credits":1,"description":"Reading and discussion, with grammar review, of intermediate-level Latin passages selected to illuminate the history, society and culture of ancient Rome and its empire. Readings from writers such as Caesar, Cicero, Sallust, Catullus, Ovid and Martial. Language course not taught in English.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/latin-latin/200/latin-210","sections":[{"days":"MWF","room":"101","types":["Cultural Diversity Course","Proseminar"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"10:50:00","meetings":[{"days":"MWF","room":"101","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"101","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Anne C. Feltovich"]},{"days":null,"room":null,"types":["Cultural Diversity Course","Proseminar"],"status":"open","section":"75","building":null,"capacity":16,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Anne C. Feltovich"]}]},
{"code":"LATIN 390","title":"Topic: Apuleius and Augustine","department":"Latin","credits":1,"description":"Reading and discussion of original Latin texts that cast light on the history, society and culture of Rome and the ancient Mediterranean. Authors and topics vary. May be retaken for credit. >","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/latin-latin/300/latin-390","sections":[{"days":"TR","room":"210","types":["Cultural Diversity Course"],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"14:15:00","meetings":[{"days":"TR","room":"210","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"210","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Amy A. Koenig"]}]},
{"code":"LING 257","title":"Lang, Gender & Sexuality","department":"Linguistics","credits":1,"description":"Stresses special lessons that anthropology has to teach about the gendered facets of linguistic expression, including the necessity of an approach that is both empirical, including moments of interaction, and critical, exploring issues of power and agency. Considers conceptual benefits and limitations to using gendered difference as a model for sexual difference in the study of linguistic expression. Prerequisites, one course in anthropology or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ling-linguistics/200/ling-257","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"75","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Spencer C. Chen"]}]},
{"code":"LIT 110W","title":"Global Gothic","department":"Literature","credits":1,"description":"The Gothic has always been global, with transcontinental monster hunts in novels like Frankenstein and Dracula. The tropes such as ghosts, monsters, and haunted houses in the Gothic can be readily adapted from one context into another with no shortage of scares and terrors. Writers and filmmakers from disparate times and places have contributed to this genre and tradition, exploring topics like slavery, colonialism, immigration, and technology. This course will examine how the Gothic reflects people's fears and anxieties through sociopolitical, historical, and transnational contexts. We will read works by writers. such as Toni Morrison, Jean Rhys, Sylvia Moreno-Garcia, and Nick Joaquin and view films like His House, Pulse, and Parasite. (Genre or Intermedia)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-110","sections":[{"days":"MWF","room":"121","types":["First Year Courses","Proseminar","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"10:50:00","meetings":[{"days":"MWF","room":"121","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"121","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Patrick Joseph Caoile"]}]},
{"code":"LIT 118W","title":"Food in Lit & Film","department":"Literature","credits":1,"description":"Always a necessity and sometimes a luxury, food connects all people to the planet and to one another. This course will explore how authors and filmmakers use food and cooking in their works as a means of exposing complex social relationships, histories, and identities. The list of authors we may read includes Laura Esquivel, Aimee Bender, Isak Dinesen, Franz Kafka, MFK Fisher, Ruth Reichl, and many poets. We will also look at films such as Big Night; Eat, Drink, Man, Woman; and Ratatouille. (Intermedia)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-118","sections":[{"days":"MWF","room":"122","types":["First Year Courses","Proseminar","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"09:50:00","meetings":[{"days":"MWF","room":"122","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"122","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Naomi E. Guttman"]},{"days":"MWF","room":"122","types":["First Year Courses","Proseminar","Writing Intensive Courses"],"status":"open","section":"02","building":"List Center","capacity":16,"comments":"Open to First Years Only","end_time":"10:50:00","meetings":[{"days":"MWF","room":"122","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"122","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Naomi E. Guttman"]}]},
{"code":"LIT 120","title":"Intro Hist & Theory Film","department":"Literature","credits":1,"description":"A general introduction to the wide world of cinema and cinema studies, focusing on crucial films from many cinematic traditions. Topics include the evolution of film from earlier forms of motion picture, the articulation and exploitation of a narrative language for cinema, the development of typical commercial genres, and the appearance of a variety of forms of critical cinema. Focuses on basic film terminology, with the cinematic apparatus and ongoing theoretical conversation about cinema and its audience.","cross_listed":["ARTH 120","CNMS 120"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-120","sections":[{"days":"MW","room":"125","types":["Cinema and Media Studies"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"22:00:00","meetings":[{"days":"MW","room":"125","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"22:00","start_date":"2026-08-27","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Scott M. MacDonald"]}]},
{"code":"LIT 127W","title":"Medieval Monsters & Marvels","department":"Literature","credits":1,"description":"This course will study medieval Britain through its monsters, asking how these aberrant figures manifest the deepest fears and desires of their authors. From Arthurian legends through the world of the Crusades, supernatural figures like fairy lovers, evil giants, loyal werewolves, and cannibal kings negotiate English conceptions of gender, race, and nation. Texts (in modern English translation) may include Beowulf, the Lais of Marie de France, Sir Gawain and the Green Knight, Sir Orfeo, the King of Tars, Mandeville's Travels, and Richard Coeur de Lion.","cross_listed":["MDRST 127W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-127","sections":[{"days":"MWF","room":"121","types":["First Year Courses","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"09:50:00","meetings":[{"days":"MWF","room":"121","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"121","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Katherine H. Terrell"]}]},
{"code":"LIT 128W","title":"American Ghosts","department":"Literature","credits":1,"description":"Why do we tell ghost stories, and what role do ghosts play in American history and literature? This course will explore the ghost narrative in short fiction, novels and film. We will examine what ghosts express in U.S. literature and culture, how they unearth our understanding of American history, and how ghost stories intersect with gender, race, sexuality and class. We will read works by Shirley Jackson, Toni Morrison, Carmen Maria Machado, Viet Thanh Nguyen, Jesmyn Ward and Louise Erdrich, among others. Students will engage in close reading and textual analysis and will write four full-length essays. (Genre) (SSIH)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-128","sections":[{"days":"TR","room":"122","types":["First Year Courses","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Not open to students who have taken a writing-intensive course at the 100 or 200-level in the LIT dept.","end_time":"15:45:00","meetings":[{"days":"TR","room":"122","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"122","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Anne E. Valente"]}]},
{"code":"LIT 136W","title":"Performing Revenge","department":"Literature","credits":1,"description":"Explores literature & film of 3 cultures fascinated by spectacles of revenge: Ancient Greece, Renaissance England, contemporary Hollywood. In these works, murder, mutilation, cannibalism, torture, and rape not only motivate revenge, but become its means. Is this only fitting or a gross paradox? What is the morality of vengeance-taking or its relationship to justice? What are the consequences for the individual and society? Texts include The Oresteia; Medea; The Spanish Tragedy; Titus Andronicus; The Duchess of Malfi; Arden of Faversham; The Crow; Sweeney Todd; Kill Bill. (Genre or Intermedia)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-136","sections":[{"days":"TR","room":"124","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"10:15:00","meetings":[{"days":"TR","room":"124","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"124","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Stephanie M. Bahr"]}]},
{"code":"LIT 147W","title":"Representing Place","department":"Literature","credits":1,"description":"Place is important to how we conceptualize things in the world, to creating both new ideas and for thinking about the past, and sometimes fundamental to our sense of identity. What gives meaning to the places you inhabit? How do you know? How do we use and think about place and space? With these basic questions, we will read, write and think about the power of place in literature, the arts and culture. Although the course has an emphasis on literature in English, we will cross 500 years of culture. Readings range from Thomas More's Utopia to Michel Foucault's meditations on cemeteries, from travel writing to Agnes Callard's analysis of travel, from map theory to urban planning scholarship. (Theory)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-147","sections":[{"days":"TR","room":"218","types":["First Year Courses","Proseminar","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years only. (FYC)","end_time":"14:15:00","meetings":[{"days":"TR","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Stephen H. Schillinger"]}]},
{"code":"LIT 148W","title":"Echoes in Literature","department":"Literature","credits":1,"description":"An exploration of literary repetitions of different kinds, both within and across texts. How might the repetition of a single detail-an image, a character, even a phrase-yield multiple interpretations? What changes when a story moves from one genre, language, or cultural context to another? How are classics like Shakespeare's The Tempest or Valmiki's Ramayana rewritten to speak to contemporary concerns? Considering multiple \"tellings\" of a single story, we will probe concepts like originality, authenticity, homage, and plagiarism. Work by Chimamanda Adichie, Aimé Césaire, and Kamila Shamsie. (Genre or Intermedia)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-148","sections":[{"days":"TR","room":"218","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"11:45:00","meetings":[{"days":"TR","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Pavitra Sundar"]}]},
{"code":"LIT 151W","title":"Fiction and Autobiography","department":"Literature","credits":1,"description":"To study African American literature is to contend with the complexity of identity and belonging-How do we understand, or not, a unitary racial identity? Who are the \"We\" that cohere identity? What is the collective, and what is the personal? Our study explores how mid-to-late 20th-century writers advance and rewrite the boundaries of genre, questioning, for example, the relationship between fiction and autobiography. This course explores the innovative ways that black writers have reimagined their places in the nation and responded to the efficacy of identity, of race, gender, and sexuality, as ways to understand the self and the collective. Texts will include Audre Lorde's Zami, Jamaica Kincaid's Lucy, Rita Dove's Thomas and Beulah, selections from Essex Hemphill, and more. (Genre or Theory) (SSIH)","cross_listed":["AFRST 151W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-151","sections":[{"days":"WF","room":"225","types":["First Year Courses","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"09:45:00","meetings":[{"days":"WF","room":"225","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"225","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Tara M. Holman"]}]},
{"code":"LIT 157W","title":"Anna Karenina Page & Screen","department":"Literature","credits":1,"description":"Does reading for pleasure differ from reading for a class? How does one interpret texts? What does it mean to read between the lines? Focusing on Leo Tolstoy's Anna Karenina we will learn to identify literary devices, themes, and symbols. Comparing different English versions we'll explore how word choices shape our interpretation. In addition to articulating our views during in-class discussions, we will write compelling interpretive and argumentative essays. Beyond the novel itself, we will consider secondary literature to discuss Anna Karenina's reception history, and consult film adaptations to analyze how text is transformed through cinematic techniques. Knowledge of Russian not required.","cross_listed":["RSNST 157W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-157","sections":[{"days":"TR","room":"1004","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":16,"comments":"Open to First-Years Only. Students are restricted to one 100-level writing-intensive LIT course. 100-level LIT courses may not be taken after 200-level LIT courses.","end_time":"10:15:00","meetings":[{"days":"TR","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Ani Abrahamyan"]}]},
{"code":"LIT 158W","title":"American #cottagecore","department":"Literature","credits":1,"description":"From Henry David Thoreau's Walden to Taylor Swift's Folklore, Americans have long romanticized \"returning to the land.\" But whose land is it, and who is - and who isn't - permitted to \"return\" to it? We'll examine depictions of the relationship between humans and nature by reading environmental literature alongside the cottagecore online aesthetic. In addition to Walden, readings may include A Son of the Forest (the first autobiography written by a Native American), The Land of Little Rain (an early feminist account of life in the California desert), and Silent Spring (the book that helped launch the environmental movement of the 1970s). We will analyze how these works - and their cottagecore social media cousins - reinforce, revise, or refuse idealizations of a simple \"return\" to nature. (Genre)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/100/lit-158","sections":[{"days":"MWF","room":"121","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":null,"end_time":"13:50:00","meetings":[{"days":"MWF","room":"121","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"121","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Claire Burdick"]}]},
{"code":"LIT 204W","title":"Poetry & Poetics","department":"Literature","credits":1,"description":"This course examines how poems work: how they are constructed, and how they produce meaning, pleasure, and cultural value. We will study poetry in terms of prosody, conventions, history, genre, and reception, with the goal of teaching the essential skills of close reading and contextual interpretation. Readings are primarily from the traditions of poetry written in English. Prerequisites, For first-years, one course in literature. No prerequisite for upperclass students. Not open to senior English or Creative Writing concentrators. (Genre or History)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-204","sections":[{"days":"MWF","room":"229","types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"List Center","capacity":18,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Not open to senior English or Creative Writing concentrators.","end_time":"09:50:00","meetings":[{"days":"MWF","room":"229","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"229","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Benjamin Widiss"]},{"days":"MWF","room":"229","types":["Writing Intensive Courses"],"status":"open","section":"02","building":"List Center","capacity":18,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Not open to senior English or Creative Writing concentrators.","end_time":"11:50:00","meetings":[{"days":"MWF","room":"229","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"229","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Claire Burdick"]},{"days":"MWF","room":"229","types":["Writing Intensive Courses"],"status":"waitlisted","section":"03","building":"List Center","capacity":18,"comments":"Open to Srs., Jrs., Soph., & 1st Yrs. Not open to senior English or Creative Writing concentrators.","end_time":"10:50:00","meetings":[{"days":"MWF","room":"229","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"229","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Benjamin Widiss"]}]},
{"code":"LIT 212","title":"Reading Blackness","department":"Literature","credits":1,"description":"Blackness is a wide-ranging conversation, a highly debated idea in culture and in scholarship. This course introduces students to a survey of academic concerns surrounding Blackness in literature and various interpretive fields. Students will follow three major thinkers, W.E.B. Du Bois, Hortense Spillers, and Frantz Fanon, and their theories of Blackness as consciousness, as text, and as surface. In addition, students will apply their approaches to two novels by Toni Morrison and Ralph Ellison. By investigating how Blackness gets written and conceived as a concept in critical writing and fiction, students will develop a more robust understanding of race and how to apply it in academic discourse. In addition, this class introduces students to reading theory and peer-reviewed writing, where they will learn how to break down arguments and identify lines of inquiry. (History)","cross_listed":["AFRST 212"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-212","sections":[{"days":"TR","room":"227","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"227","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"227","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Tara M. Holman"]}]},
{"code":"LIT 214","title":"Style: a Writer's Bootcamp","department":"Literature","credits":0.25,"description":"Style has power; the goal of this course is to help you harness that power. Psychology research has shown that attractive people are assumed to be more intelligent and skilled; so too is elegant prose deemed more intelligent and persuasive. This quarter credit course explicitly considers and cultivates style. What is stylistically effective in literary criticism and why? In other modes of writing? How can we develop an effective style of our own? This workshop is divided between the analysis of sample texts and hands-on revision. (0.25 credit)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-214","sections":[{"days":"W","room":"122","types":[],"status":"open","section":"01","building":"List Center","capacity":12,"comments":"Course runs 8/27/26-10/21/26. 0.25 credit","end_time":"12:15:00","meetings":[{"days":"W","room":"122","type":"LEC","building":"List Center","end_date":"2026-10-21","end_time":"12:15","start_date":"2026-08-27","start_time":"11:00"}],"start_time":"11:00:00","instructors":["Stephanie M. Bahr"]}]},
{"code":"LIT 222W","title":"Chaucer:gender & Genre","department":"Literature","credits":1,"description":"Examines how Chaucer engages and transforms prevailing medieval ideas of gender and genre. Particular emphasis on his constructions of masculinity and femininity in relation to themes of sex, religion, social power and narrative authority. Readings include \"Troilus and Criseyde\" and \"The Canterbury Tales in Middle English,\" as well as select medieval sources and modern criticism. (History)","cross_listed":["MDRST 222W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-222","sections":[{"days":"MWF","room":"218","types":["Medieval & Renaissance St","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":18,"comments":null,"end_time":"13:50:00","meetings":[{"days":"MWF","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Katherine H. Terrell"]}]},
{"code":"LIT 227","title":"Shakespeare","department":"Literature","credits":1,"description":"This course is about developing the reading strategies to not only understand and enjoy Shakespeare's plays, but to read them in a complicated, critical way. While we will study plays spanning Shakespeare's career, the course will place a special emphasis on reading the plays attuned to how different genres (tragedy, comedy, romance, pastoral, history) are employed and explored. Additionally, we will read significant, complementary material about the culture and the theatre during Shakespeare's lifetime. This course will also make use of the Special Collections. (History or Intermedia)","cross_listed":["MDRST 227"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-227","sections":[{"days":"TR","room":"124","types":[],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Juniors & Seniors Only","end_time":"11:45:00","meetings":[{"days":"TR","room":"124","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"124","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Stephanie M. Bahr"]}]},
{"code":"LIT 239","title":"Japan:a-bomb to Dragon Ball Z","department":"Literature","credits":1,"description":"This course delves into the complexities of modern Japan, placing a particular emphasis on pivotal topics such as military conflicts, the pursuit of pacifism, the experience of nuclear victimhood, periods of foreign occupation, and the concept of social responsibility. To achieve a deeper understanding of these themes and to appreciate their varied representations, we employ a multifaceted approach. Our exploration encompasses a range of media forms, including films, radio broadcasts, literary works, and digital archives. Additionally, we will delve into a diverse array of genres, spanning from documentary and war propaganda to personal storytelling. Through these diverse lenses, we aim to cultivate a more nuanced and multifaceted understanding of these historical narratives. Taught in English. No knowledge of Japanese language or history required. (SSIH)","cross_listed":["CNMS 239","JAPN 239"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-239","sections":[{"days":"WF","room":"207","types":["Asian Studies","Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"Benedict Hall","capacity":20,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Kyoko Omori"]}]},
{"code":"LIT 265","title":"Indigenous North American Lit","department":"Literature","credits":1,"description":"This course will focus on contemporary literature, film, poetry, and creative nonfiction written by North American Indigenous authors from various nations within both the United States and Canada with attention to colony and empire, climate change, sovereignty, emergent indigeneity, and multispecies kinship. As much as possible, we will place these texts within their historical, culturally-specific, and national contexts, as well as in relation to each other and to ourselves in our classroom at Hamilton. Texts may include works by Louise Erdrich, N. Scott Momaday, Leslie Marmon Silko, Robin Wall Kimmerer, Leanne Simpson, Rebecca Nagle, Lisa Jackson, Stephen Graham Jones, Thomas King, Tommy Pico, Cherie Dimaline, and Danis Goulet. (Genre or History) (SSIH)","cross_listed":["ENVST 265"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-265","sections":[{"days":"TR","room":"3021","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:45:00","meetings":[{"days":"TR","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Brianna R. Burke"]}]},
{"code":"LIT 269","title":"Climate Fiction & Film","department":"Literature","credits":1,"description":"In this course, we will examine how fiction and film about the climate crisis document our anxieties, remediate our ecologies, and reimagine our climate futures. Students will be introduced to Ecocriticism and the Environmental Humanities while reading and watching across subgenres; a portion of the course will include American Indian and First Nations texts. Course materials will include contemporary novels, short stories, film, media, and theory. Our class screenings and discussions will be supplemented by visits from writers and filmmakers thinking through the social, ethical, and political implications of making media about the climate crisis. (Intermedia or Theory)","cross_listed":["ENVST 269"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-269","sections":[{"days":"TR","room":"3021","types":[],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Srs, Jrs, and Sophomores","end_time":"10:15:00","meetings":[{"days":"TR","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Brianna R. Burke"]}]},
{"code":"LIT 278","title":"Rethinking the Romance","department":"Literature","credits":1,"description":"A study of the ways in which literary works shape and are shaped by conventional beliefs about love and happiness. How do representations of romance serve aesthetic and political ends? How does fiction navigate the gap between truth (what is real) and desire (what is wished for)? Special attention to texts that reflect on the (sexual, psychological, and/or political) \"abnormal.\" Readings will include theory as well as literary texts by such authors as Diderot, Sand, Austen, Wilde, and Moravia. (Genre or Theory) (SSIH)","cross_listed":["WMGST 278"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-278","sections":[{"days":"TR","room":"229","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"10:15:00","meetings":[{"days":"TR","room":"229","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"229","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Suzanne Taylor"]}]},
{"code":"LIT 283","title":"Intro Asian-amer Lit","department":"Literature","credits":1,"description":"Examination of themes, forms, and history of literary production by people of Asian descent in the United States. We will survey translated and English-language works by Asian American writers of varying ethnic affiliations, including Chinese, Japanese, Filipino, Korean, Indian, and others. We'll explore how each writer negotiates a relationship with a particular cultural heritage, as well as confronts the racial, cultural, and political formations of the U.S.. Authors include Maxine Hong Kingston, Carlos Bulosan, John Okada, the Angel Island poets, and others. (History or Theory) (SSIH)","cross_listed":["AMST 283"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-283","sections":[{"days":"MW","room":"227","types":["Asian Studies","Diversity Course","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":"Open to Srs., Jrs., & Sophomores","end_time":"14:15:00","meetings":[{"days":"MW","room":"227","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"227","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Steven G. Yao"]}]},
{"code":"LIT 284","title":"Intro Af Am Lit & Theory","department":"Literature","credits":1,"description":"How do we make sense of the long durée of African American literary history and scholarship from Early Atlantic literature into the present? This course introduces a set of critical concerns across African American literature and theory and meditates on ongoing concerns that are core to the discipline of Black thought. Students will read interdisciplinarily and across a variety of time periods around concepts of canon and genre, identity and consciousness, music and expressivity, and representation and realism. Thinkers will include: Phillis Wheatley, Frederick Douglass, Richard Wright, Zora Neale Hurston, Ralph Ellison, Gwendolyn Brooks, Angela Davis, Hoyt Fuller, Fred Moten, etc. (History or Theory) (SSIH)","cross_listed":["AFRST 284"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-284","sections":[{"days":"TR","room":"120","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"120","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"120","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Tara M. Holman"]}]},
{"code":"LIT 286","title":"Dostoevsky's Polyphonic World","department":"Literature","credits":1,"description":"This course offers a deep and wide-ranging exploration of the fiction of the Russian writer, Fyodor Dostoevsky. Students will read \"Notes From the Underground,\" his groundbreaking early novella, as well as two of his great, long-form novels: \"Crime and Punishment\" and \"Brothers Karamazov.\" The theorist Mikhail Bakhtin characterized Dostoevsky's experimental novels as \"polyphonic,\" in that the author let his characters speak as a discordant chorus of distinctive voices, rather than himself speaking in an authoritative, \"monologic,\" authorial voice. Dostoevsky's polyphonic novels gave profound expression to diverse contemporary ideas about politics, philosophy, religion, and human nature, in spite of the author's own vehemently nationalist, imperialist, and xenophobic views.","cross_listed":["RSNST 286"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-286","sections":[{"days":"TR","room":"222","types":[],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"15:45:00","meetings":[{"days":"TR","room":"222","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"222","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Jason A. Cieply"]}]},
{"code":"LIT 289","title":"Video Essays","department":"Literature","credits":0.5,"description":"Videographic criticism is a multimodal form of writing. In using sound and image to comment on audiovisual texts, the video essay blurs the line between object and method of study. This hands-on humanities lab introduces students to a wide range of videographic techniques and formats, and some of the theoretical and philosophical concerns driving recent developments in the field. Students learn to not only craft their own video essays, but display greater reflexivity about their aesthetic choices, interventions and compositional process. No prior editing or other digital experience required.","cross_listed":["CNMS 289"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-289","sections":[{"days":"TR","room":"144","types":[],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Course runs 8/27/26-10/21/26. 0.5 credit","end_time":"15:45:00","meetings":[{"days":"TR","room":"144","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-10-21","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"144","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-10-21","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Pavitra Sundar"]}]},
{"code":"LIT 290","title":"Hist Documentary Cinema","department":"Literature","credits":1,"description":"The history of cinema as representation and interpretation of \"reality,\" focusing on nonfiction film and video from a variety of periods and geographic locales. Emphasis on the ways in which nonfiction films can subvert viewers'' conventional expectations and their personal security. Forms to be discussed include the city symphony, ethnographic documentary, propaganda, nature film, direct cinema, cinma vrit, the compilation film and personal documentary.","cross_listed":["ARTH 290","CNMS 290"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-290","sections":[{"days":"T","room":"125","types":[],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"22:00:00","meetings":[{"days":"T","room":"125","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"22:00","start_date":"2026-08-27","start_time":"19:00"},{"days":"R","room":"125","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"124","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"T","room":"124","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"22:00","start_date":"2026-08-27","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Scott M. MacDonald"]}]},
{"code":"LIT 293","title":"The Making of English","department":"Literature","credits":1,"description":"History of the English language from its origins in Old English to its present-day proliferation into World English(es). Particular attention to how the internal development of English (its sound system, syntax, grammar and vocabulary) relates to political and cultural transformations among English-speaking peoples throughout history, and how the English language continues to provoke political and cultural controversy. (History)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/200/lit-293","sections":[{"days":"MWF","room":"227","types":[],"status":"open","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"227","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"227","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Katherine H. Terrell"]}]},
{"code":"LIT 305","title":"The Rich & the Poor:market","department":"Literature","credits":1,"description":"In-depth study of how new economic theories and practices in the 18th and 19th centuries shaped and were shaped by the novel form. We examine how novels helped readers adapt to a new commercial society born out of the industrial revolution and British Imperialism. Reading fictional representations of old, new, and hypothetical worlds, we examine how economic and cultural commerce transformed ideas about human nature and, by extension, institutions like education, marriage, and government. Authors may include Defoe, Adam Smith, Captain Cook, Quobna Ottobah Cugoano, Austen, Dickens, and Eliot. This will also be a Methods course, focused on learning disciplinary research. (History or Theory) (SSIH)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/300/lit-305","sections":[{"days":"TR","room":"225","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"List Center","capacity":12,"comments":null,"end_time":"14:15:00","meetings":[{"days":"TR","room":"225","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"225","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Suzanne Taylor"]}]},
{"code":"LIT 314W","title":"The New Confessional","department":"Literature","credits":1,"description":"Sylvia Plath said \"I, who reportedly write so truthfully about myself, so openly, am not that open.\" In this course we'lltrace the ways poets have subverted and expanded our notion of what the confessional poem is, from its 1957 debut,(Robert Lowell's Still Life) to the 21st century. Readings will include Sylvia Plath, Anne Sexton, Audre Lorde, Adrienne Rich, John Berryman, Ntozake Shange, Sandra Cisneros, Afaa Weaver, Maggie Nelson, Sharon Olds, Judy Jordon, and Ocean Vuong, among others. (Genre) (SSIH)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/300/lit-314","sections":[{"days":"F","room":"225","types":["Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":18,"comments":"Open to Srs., Jrs., and Sophomores","end_time":"16:00:00","meetings":[{"days":"F","room":"225","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"225","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Jane E. Springer"]}]},
{"code":"LIT 315W","title":"Literary Theory and Study","department":"Literature","credits":1,"description":"In this course we will explore some of the main developments in literary and cultural \"theory\" during the twentieth and twenty-first centuries. Topics may include historicism, formalism, structuralism, deconstruction, Marxism, and feminism, theories of race, nationalism, gender and sexuality, of materiality and the digital culture, ecocriticism and disability theory. Methods. (History or Theory)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/300/lit-315","sections":[{"days":"MWF","room":"231","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":12,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"231","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"231","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Steven G. Yao"]}]},
{"code":"LIT 320W","title":"Indians, Aliens, Others","department":"Literature","credits":1,"description":"The world is full of strange beings, some from outer space, others close to home. What leaps of imagination must we make to close the physical, cultural, philosophical, and linguistic gulf between \"us\" and \"them\"? How might encounters with \"others\" change our conceptions of self and our habits of thinking, feeling, and sensing? Readings include postcolonial and science-fiction texts by writers (and filmmakers) such as Octavia Butler, Ursula Le Guin, Indra Sinha, and Neill Blomkamp. Theoretical frameworks will span postcolonial, queer, and disability studies. Course is graded S/U. (Theory) (SSIH)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/300/lit-320","sections":[{"days":"TR","room":"218","types":["Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":18,"comments":"Course is graded Satisfactory/Unsatisfactory.","end_time":"10:15:00","meetings":[{"days":"TR","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Pavitra Sundar"]}]},
{"code":"LIT 332W","title":"Renaissance Drama","department":"Literature","credits":1,"description":"The course focuses on Renaissance drama, a time when playhouses faced censorship, plague closures and competition from bears wrestling dogs. From being murdered, to prison sentences, to death by plague, many of the writers had a hard time too. We will study plays (some obscure, some quite strange, other rather famous, all enormously interesting) from this very rich and volatile period of literary history. (Genre or History)","cross_listed":["MDRST 332W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/300/lit-332","sections":[{"days":"TR","room":"218","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":18,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Stephen H. Schillinger"]}]},
{"code":"LIT 447","title":"Seminar: James Joyce","department":"Literature","credits":1,"description":"In-depth study of Joyce's major works in their historical and cultural contexts. Readings include Dubliners and Finnegans Wake, Major emphasis on Ulysses. (Genre or History)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/400/lit-447","sections":[{"days":"F","room":"120","types":[],"status":"open","section":"01","building":"List Center","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":"120","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"120","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Steven G. Yao"]}]},
{"code":"LIT 496","title":"Seminar: Independent Projects","department":"Literature","credits":0.5,"description":"This course provides students pursuing honors in Literature structured support for advanced research. Seminar sessions will explore the conceptual frameworks underlying various approaches to academic criticism, as well as pragmatic matters including research tools and methods, writing and revision strategies, time management, &c. Students will share and critique one another's drafts.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/lit-literature/400/lit-496","sections":[{"days":"W","room":"120","types":[],"status":"open","section":"01","building":"List Center","capacity":12,"comments":"Course is graded Satisfactory/Unsatisfactory.","end_time":"14:15:00","meetings":[{"days":"W","room":"120","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"120","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Suzanne Taylor"]}]},
{"code":"LTAM 107W","title":"US Borderlands","department":"Latin American Studies","credits":1,"description":"This course asks how territorial boundaries have evolved into a dispersed, interior regime of surveillance and control over the course of American history. Beginning with colonial-era treaties and other practices of boundary-making in early US history, we will turn to examine U.S.-Mexico borderlands as a region shaped not only by movement, exchange, and cultural intermingling, but also by the evolving power of the state and the contested processes of border-making. Special emphasis will be given to the intertwined histories of Indigenous, Mexican, Black, Chinese, and Euro-American communities and to examining how borders are produced, negotiated, and lived, while developing critical reading and writing skills in history.","cross_listed":["HIST 107W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/hist-history/100/hist-107","sections":[{"days":"MWF","room":"103","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":"Open to 1st Yrs and Sophomores Only","end_time":"10:50:00","meetings":[{"days":"MWF","room":"103","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"103","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Nahomi Esquivel"]}]},
{"code":"MATH 113","title":"Calculus I","department":"Mathematics","credits":1,"description":"Introduction to the differential and integral calculus of a single variable. Topics include limits, continuity, derivatives, max-min problems and integrals. This course may not be counted toward the concentration or minor. Four hours of class.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/math-mathematics-and-statistics/100/math-113","sections":[{"days":"MTWF","room":"222","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MTWF","room":"222","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"W","room":"G041","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"09:00:00","instructors":["James J. Burton"]},{"days":"MWF","room":"127","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"127","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"T","room":"101","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"202","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Rayan Ibrahim"]},{"days":"MWRF","room":"222","types":["First Year Courses","Qlit Course","Quantitative & Symbolic R"],"status":"waitlisted","sect