{"code":"MATH 116","title":"Calculus II","department":"Mathematics","credits":1,"description":"A continuation of the study begun in MATH 113. Methods of integration, improper integrals, applications of integration to volume and arc length, parametric equations, sequences and series, power series, vectors, and an introduction to 3-dimensional coordinate systems with equations of lines and planes.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/math-mathematics-and-statistics/100/math-116","sections":[{"days":"MWF","room":"222","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"222","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"T","room":"G027","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"},{"days":"W","room":"G027","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"10:00:00","instructors":["Andrew Stocker"]},{"days":"MWF","room":"225","types":["Quantitative & Symbolic R"],"status":"open","section":"02","building":"C.A. Johnson Bldg.","capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"225","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"305","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"},{"days":"W","room":"2048","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start