{"code":"MUSIC 141","title":"Group Performance","department":"Music","credits":0.25,"description":"The study of music through performance in one or more of the following: Orchestra, Brass Lab, Woodwind Lab, College Choir, Masterworks Chorale, Jazz Ensemble, Jazz Improvisation, Percussion Ensemble, and Piano Duets. Prerequisites: consent of instructor. One-quarter course credit each semester. May be repeated. Students may count up to four credits from among 141, 142, 241 and 242 toward graduation.","cross_listed":[],"catalog_url":null,"sections":[{"days":"MW","room":"HALL","types":["Group Performance"],"status":"waitlisted","section":"01","building":"Wellin Hall","capacity":40,"comments":"Instructor's Signature Required","end_time":"21:00:00","meetings":[{"days":"MW","room":"HALL","type":"LEC","building":"Wellin Hall","end_date":"2026-12-11","end_time":"21:00","start_date":"2026-08-27","start_time":"19:00"},{"days":"MW","room":"106","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"21:00","start_date":"2026-08-27","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Charlotte Botha"]},{"days":"U","room":"104","types":["Group Performance"],"status":"open","section":"03","building":"List Center","capacity":40,"comments":"Instructor's Signature Required","end_time":"20:30:00","meetings":[{"days":"U","room":"104","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"20:30","start_date":"2026-08-27","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Heather R. Buchman"]},{"days":null,"room":null,"types":["Group Performance"],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Stephanie Carbone"]},{"days":"TR","room":"HALL","types":["Group Performance"],"status":"waitlisted","section":"06","building":"Wellin Hall","capacity":40,"comments":"Instructor's Signature Required","end_time":"21:00:00","meetings":[{"days":"TR","r