tart_time":"19:00:00","instructors":["Charlotte Botha"]}]},
{"code":"MUSIC 161","title":"Jazz Foundations","department":"Music","credits":1,"description":"A survey of jazz history from its roots in West African culture to the present day. Provides an analysis of jazz styles (i.e., blues, ragtime, New Orleans Jazz, swing, cool jazz, bebop, hard bop, modal jazz, free jazz) and a brief overview of the lives and music of influential jazz artists including Louis Armstrong, Duke Ellington, Billie Holiday, Mary Lou Williams, Charlie Parker, Miles Davis, John Coltrane, Marian McPartland, Wynton Marsalis, and Ingrid Jensen. Includes a study of the social and the political context of the music and the way jazz has interfaced with social movements over the course of the 20th and 21st centuries. Students will analyze power structures based on race and gender, and their consequences in the jazz field. Not open to students who have taken MUSIC/AFRST 160/260 or MUSIC/AFRST 259/359.","cross_listed":["AFRST 161","AFRST 261","MUSIC 261"],"catalog_url":null,"sections":[{"days":"TR","room":"106","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":"106","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"106","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Gabriel Condon"]}]},
{"code":"MUSIC 180","title":"Basic Aural Skills","department":"Music","credits":0.25,"description":"Introduction to aural understanding through sight-singing, dictation and the rudiments of music notation. Diatonic major scales and keys, diatonic intervals, diatonic melodies, tonic and dominant arpeggiation, an introduction to minor scales and keys, cadences, rhythms in simple and compound meters. One-quarter course credit. May be repeated for credit with consent of instructor. Prerequisites, ability to read music in one clef.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/100/music-180","sections":[{"days":"TR","room":"201","types":[],"status":"open","section":"01","building":"Schambach Center","capacity":40,"comments":null,"end_time":"12:50:00","meetings":[{"days":"TR","room":"201","type":"LEC","building":"Schambach Center","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"}],"start_time":"12:00:00","instructors":["Charlotte Botha"]}]},
{"code":"MUSIC 181","title":"Basic Keyboard Skills","department":"Music","credits":0.25,"description":"Introduction to keyboard skills including note identification, intervals, major and minor scales, triad identification, 7th chords, simple chord progressions and basic sight-reading. One-quarter course credit. May be repeated for credit with consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/100/music-181","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Stephen H. Best"]},{"days":null,"room":null,"types":[],"status":"open","section":"90","building":null,"capacity":40,"comments":"Registration will begin in August. Instructor's Signature Required.","end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"MUSIC 210","title":"Fundamntl & Chrom Harmony","department":"Music","credits":1,"description":"Intensive training in the elements of music, with an emphasis on the study of melody, intervals, chords, rhythm and meter, and basic musical forms. Special attention devoted to harmonic progressions and chromatic harmony. Regular written assignments, including computer assignments aimed to develop musicianship skills. Prerequisites, the ability to read music in both treble and bass clefs, and basic knowledge of (1) key and meter signatures, (2) major and minor scales, and (3) simple rhythms. Not open to students who have taken Music 110. Students who have taken Music 110 and wish to continue with music theory should take Music 211. Potential music concentrators should strongly consider taking Music 180 or Music 181 concurrently.","cross_listed":["MUSIC 211"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/200/music-210","sections":[{"days":"MW","room":"108","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Schambach Center","capacity":40,"comments":"No open to those who took MUSIC 110","end_time":"14:15:00","meetings":[{"days":"MW","room":"108","type":"LEC","building":"Schambach Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"108","type":"FINAL","building":"Schambach Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Ryan C. Carter"]}]},
{"code":"MUSIC 211","title":"Chromatic Harmony","department":"Music","credits":0.5,"description":"(Same as second half of MUS 210.) Regular written assignments, including computer assignments aimed to develop musicianship skills. One-half course credit. Not open to students who have taken Music 210. Students who have taken Music 110 and wish to continue with music theory should take Music 211. Otherwise, students can place into 211 by passing the Music Department theory placement exam, or earning a 5 on the AP Music Theory Exam. Students who complete 211 with a grade of B or higher, and who have not earned a credit in 110, will earn an additional AP half credit. Music concentrators should strongly consider taking Music 180 or 181 concurrently.","cross_listed":["MUSIC 210"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/200/music-211","sections":[{"days":"MW","room":"108","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Schambach Center","capacity":40,"comments":null,"end_time":"14:15:00","meetings":[{"days":"MW","room":"108","type":"LEC","building":"Schambach Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"108","type":"FINAL","building":"Schambach Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Ryan C. Carter"]}]},
{"code":"MUSIC 217","title":"Roots to Country Music","department":"Music","credits":1,"description":"Study of country music from its roots in cowboy songs, fiddle tunes, blues, bluegrass, and gospel hymns to current artists like The [Dixie] Chicks, Taylor Swift, and Brad Paisley. Artists include the Carter Family, Hank Williams, Patsy Cline, Dolly Parton, Willie Nelson, Emmylou Harris, Lynyrd Skynyrd, & Garth Brooks. Study of the musical elements, social class, gender roles, and cultural contexts of styles such as Western Swing, Honky-Tonk, Rockabilly, the Nashville Sound, Southern Rock, and Alt-country. Includes films such as \"Coal Miner's Daughter,\" \"Nashville,\" and \"O Brother, Where Art Thou?\" No previous knowledge of music required. MUSIC-217 has an additional independent project. Registration at the 200-level only with instructor's permission.","cross_listed":["AMST 217"],"catalog_url":null,"sections":[{"days":"TR","room":"106","types":["American Studies"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":"Open to Srs, Jrs, and Soph, & 1st Yrs. Instructor's signature required.","end_time":"14:15:00","meetings":[{"days":"TR","room":"106","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"106","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Lydia R. Hamessley"]}]},
{"code":"MUSIC 220","title":"From Chant to Bach","department":"Music","credits":1,"description":"Solo vocal and choral music of the Medieval, Renaissance, and Baroque eras from Gregorian chant to Bach. Topics include text expression through music, historical approaches to vocal compositional styles and performance practices (a cappella and accompanied), and responses to early music by later composers (Lauridsen, Whitacre, Respighi, Vaughan Williams, Britten, Orff, Prt). Some consideration of the use of early music in film and television (Lord of the Rings, Dangerous Liaisons, Shakespeare in Love, The Adventures of Robin Hood, and Game of Thrones).","cross_listed":["MDRST 220"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-literature-and-history-of-music/200/music-220","sections":[{"days":"TR","room":"106","types":["Medieval & Renaissance St"],"status":"open","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"106","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"106","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Lydia R. Hamessley"]}]},
{"code":"MUSIC 225","title":"Solo Performance","department":"Music","credits":0.25,"description":"The study of music through lessons in voice, flute, oboe, clarinet, bassoon, saxophone, horn, trumpet, trombone, euphonium, tuba, piano, organ, harp, percussion, classical guitar, jazz/contemporary guitar, folk guitar, violin, viola, cello, and contrabass. Half-hour tutorial for one-quarter credit. Students must participate in at least one public performance per semester. A fee is charged. Prerequisites, consent of instructor. Successful completion of Music 110, 210, 211, or the music theory placement exam must occur within three semesters of Solo Performance study. May be repeated for credit. A fee is charged.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-performance/200/music-225","sections":[{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"33","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ubaldo D. Valli"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"34","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Sar-Shalom Strong"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"56","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Kay S. Paulsen"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"71","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Edgar Tumajyan"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"75","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Alexander Bonner"]},{"days":null,"room":null,"types":["Solo Performance"],"statu