{"code":"MUSIC 240","title":"Inter Med:perf, Ritual & Tech","department":"Music","credits":1,"description":"This class will cover performance strategies in relationship to digital technology, ritual and the social. We will create collaborative and hybrid work at the intersection of performance, digital media and social practice and map out modes of ritual engagement within these intersections. We will explore \"liveness\" as a digital and/or embodied presence and survey contemporary hybrid performance work. Enrollment 16, No prerequisite.","cross_listed":["ART 240","DARTS 240","THETR 240"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-performance/200/music-240","sections":[{"days":"R","room":"143","types":["Co-Lab Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Yrs","end_time":"12:00:00","meetings":[{"days":"R","room":"143","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Anna Huff"]}]},
{"code":"MUSIC 241","title":"Advanced Group Performance","department":"Music","credits":0.25,"description":"The study of music through chamber performance in one or more of the following: Instrumental Chamber Ensembles (Buchman), Hamilton Voices (Botha), Jazz Combo (Woods). Co-requisite, concurrent registration in the corresponding Group Performance ensemble required; i.e., Orchestra, College Choir or Jazz Ensemble respectively, and consent of instructor. One-quarter course credit each semester. May be repeated. Students may count up to four credits from among 141, 142, 241 and 242 toward graduation.","cross_listed":[],"catalog_url":null,"sections":[{"days":"U","room":"104","types":["Group Performance"],"status":"open","section":"02","building":"List Center","capacity":40,"comments":null,"end_time":"20:30:00","meetings":[{"days":"U","room":"104","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"20:30","start_date":"2026-08-27","start_time":"19:00"}],"start_time":"19:00:00","instructors":["Heather R. Buchman"]},{"days":null,"room":null,"types":["Group Performance"],"status":"open","section":"03","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Allan B. Kolsky"]},{"days":null,"room":null,"types":["Group Performance"],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Edgar Tumajyan"]},{"days":null,"room":null,"types":["Group Performance"],"status":"open","section":"09A","building":null,"capacity":40,"comments":"Instructor's signature required.","end_time":null,"meetings":[],"start_time":null,"instructors":["Cornelia L. Brewster"]},{"days":null,"room":null,"types":["Group Performance"],"status":"open","section":"09E","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Suzanne S. Beevers"]},{"days":"T","room":"HALL","types":["Group Performance"],"status":"open","section":"11","building":"Wellin Hall","capacity":40,"comments":"Instructor's Signature Required","end_time":"13:00:00","meetings":[{"days":"T","room":"HALL","type":"LEC","building":"Wellin Hall","end_date":"2026-12-11","end_time":"13:00","start_date":"2026-08-27","start_time":"12:00"}],"start_time":"12:00:00","instructors":["Gabriel Condon"]}]},
{"code":"MUSIC 254","title":"Studies in World Music","department":"Music","credits":1,"description":"Examination of selected non-Western music cultures with primary emphasis on West African drumming and Javanese gamelan traditions. Focus on musical procedures as well as cultural uses of the music and corollary arts. Includes hands-on performance in the traditions studied. Next offered in fall 2021. Prerequisites, One course in music or consent of instructor. Offered every other year.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-literature-and-history-of-music/200/music-254","sections":[{"days":"TR","room":"212","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"212","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"212","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Lydia R. Hamessley"]}]},
{"code":"MUSIC 257","title":"Music & the Black Arts Mvmnt","department":"Music","credits":1,"description":"An examination of the function of music in the Black Arts Movement in the 1960s and 1970s, analyzing how music paralleled literature, drama, and visual art. The course draws connections between earlier forms of Afro-modernism in the Harlem Renaissance and demonstrates how musicians engaged in social activism by protesting systemic racism and white supremacy. The course considers Larry Neal's theory of the Black Aesthetic and Robert L. Douglas' theory of multidominant elements as lenses for interdisciplinary analysis. Includes a study of musicians who engaged in political activism during the Black Arts Movement and the Movement's influence on early hip-hop artists such as Public Enemy and Poor Righteous Teachers.","cross_listed":["AFRST 257","AFRST 357","MUSIC 357"],"catalog_url":null,"sections":[{"days":"MW","room":"201","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Schambach Center","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"201","type":"LEC","building":"Schambach Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"201","type":"FINAL","building":"Schambach Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Gabriel Condon"]}]},
{"code":"MUSIC 261","title":"Jazz Foundations","department":"Music","credits":1,"description":"A survey of jazz history from its roots in West African culture to the present day. Provides an analysis of jazz styles (i.e., blues, ragtime, New Orleans Jazz, swing, cool jazz, bebop, hard bop, modal jazz, free jazz) and a brief overview of the lives and music of influential jazz artists including Louis Armstrong, Duke Ellington, Billie Holiday, Mary Lou Williams, Charlie Parker, Miles Davis, John Coltrane, Marian McPartland, Wynton Marsalis, and Ingrid Jensen. Includes a study of the social and the political context of the music and the way jazz has interfaced with social movements over the course of the 20th and 21st centuries. Students will analyze power structures based on race and gender, and their consequences in the jazz field. Not open to students who have taken MUSIC/AFRST 160/260 or MUSIC/AFRST 259/359.","cross_listed":["AFRST 161","AFRST 261","MUSIC 161"],"catalog_url":null,"sections":[{"days":"TR","room":"106","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"List Center","capacity":40,"comments":"Instructor's signature required.","end_time":"10:15:00","meetings":[{"days":"TR","room":"106","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"106","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Gabriel Condon"]}]},
{"code":"MUSIC 270","title":"Intro Music, Sound & Tech","department":"Music","credits":1,"description":"An introduction to the essential tools of 21st-century musicians, with an emphasis on creative practice and critical reflection. Students will learn to record, edit, process, and synthesize sound digitally; produce music using MIDI keyboards and software instruments; distribute their work; and critically engage with topics linked to the emergence of digital audio technologies. Listening and reading will include a wide range of works by Halim El-Dabh, Karlheinz Stockhausen, Pauline Oliveros, Pamela Z, and others. Open to all students regardless of musical background; additional resources for relevant music theory will be provided.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/200/music-270","sections":[{"days":"MW","room":"143","types":[],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"143","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"143","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Ryan C. Carter"]}]},
{"code":"MUSIC 281","title":"Interm. Keyboard Skills","department":"Music","credits":0.5,"description":"A continuation of 181. Four-part chord progression reading, alto and tenor clef, melodic transposition, introduction to figured harmony, chord progressions, intermediate sight-reading. One-half course credit. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-theory-and-composition/200/music-281","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Stephen H. Best"]}]},
{"code":"MUSIC 316","title":"Conducting","department":"Music","credits":1,"description":"An introduction to the craft of conducting, including gestural technique, score reading and analysis, and rehearsal technique (both instrumental and choral). Focus on developing a clear, expressive and communicative technique, and on a conductor's process of learning a score. Text readings from Elizabeth Green, Markand Thakar, and Sam Adler on technique and the orchestral instruments, analysis assignments of orchestral excerpts conducted with piano, and reflections on different bodies and identities conducting (such as Natalie Stutzmann, Kwamé Ryan, Xian Zhang, Maria Schneider) culminate in leading a full orchestra. Students must be fluent reading music in both treble and bass clefs. Concurrent participation in a conducted college ensemble is encouraged.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-performance/300/music-316","sections":[{"days":"TR","room":"201","types":[],"status":"open","section":"01","building":"Schambach Center","capacity":40,"comments":"MUSIC 110, 210, or 211, or signature required","end_time":"10:15:00","meetings":[{"days":"TR","room":"201","type":"LEC","building":"Schambach Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"201","type":"FINAL","building":"Schambach Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Heather R. Buchman"]}]},
{"code":"MUSIC 326","title":"Advanced Solo Performance","department":"Music","credits":0.5,"description":"The study of music through lessons in voice, flute, oboe, clarinet, bassoon, saxophone, horn, trumpet, trombone, euphonium, tuba, piano, organ, harp, percussion, classical guitar, jazz/contemporary guitar, folk guitar, violin, viola, cello, and contrabass. Hour tutorial for one-half credit required for and open only to students who are preparing half or full recitals approved by the Music Department. Prerequisites, successful completion of at least two semesters of Solo Performance, 110 or 210, and consent of instructor. Students may only enroll in Advanced Solo Performance upon completion of or co-registration in 110, 210, or 211. May be repeated for credit. A fee is charged.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/music-performance/300/music-326","sections":[{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"32","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Allan B. Kolsky"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"56","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Kay S. Paulsen"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"66","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Elena V. Nezhdanova"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"67","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Renee M. Heitmann"]},{"days":null,"room":null,"types":["Solo Performance"],"status":"open","section":"90","building":null,"capacity":40,"comments":"Registration will begin in August. Instructor's Signature Required."