{"code":"NEURO 198","title":"Collaborative Research","department":"Neuroscience","credits":0.25,"description":"Collaborative research under the supervision of a faculty member. Focus on data collection and/or analysis. Three to four hours per week of lab work. Prerequisites, Permission of the instructor. Student performance will be evaluated as Satisfactory/Unsatisfactory. One-quarter credit per semester. May be repeated for credit, but does not count toward concentration requirements.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/100/neuro-198","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Vikranth Bejjanki"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Abigail K. Myers"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Alexandra List"]},{"days":null,"room":null,"types":[],"status":"open","section":"05","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Lok-Kin Yeung"]}]},
{"code":"NEURO 201","title":"Stats & Research Methods","department":"Neuroscience","credits":1,"description":"The application and interpretation of descriptive and inferential statistics in the study of psychological processes. Some instruction in research design and methodological issues. Students will learn to use the statistical computer program SPSS to analyze data. Topics include the principles of hypothesis testing, t tests, analysis of variance, regression, and some non-parametric statistics. Prerequisites, 101.","cross_listed":["PSYCH 201"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-201","sections":[{"days":"MWF","room":"3024","types":["Qlit Course","Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"3024","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"3024","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Siobhan Robinson"]}]},
{"code":"NEURO 205","title":"Fundamentals of Neurobio","department":"Neuroscience","credits":1,"description":"Introduction to the field of neuroscience from a biological perspective. In-depth examination of fundamental concepts in neurobiology designed to introduce students to the electrophysiological, chemical and anatomical features of neurons, brain regions and brain circuits.Investigation of the neurobiological basis of behavior through exploration of topics such as neuronal communication, neuroanatomy, sensory and motor systems, learning, motivation, and behavior disorders.","cross_listed":["BIO 205","PSYCH 205"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-205","sections":[{"days":"MWF","room":"3021","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Abigail K. Myers"]}]},
{"code":"NEURO 211","title":"Genes, Molecules, & Cells","department":"Neuroscience","credits":1,"description":"An intermediate course that examines genetics and biochemistry within the context of the cell. This course will focus on the macromolecules of life, genetic material and classical genetics, fundamental biochemical pathways, and cellular structure and function. A particular focus will be placed on proteins and nucleic acids and how cells use these molecules to direct the mechanisms of inheritance, energy production, and cellular reproduction. Three hours of class and three hours of laboratory.","cross_listed":["BIO 211"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/neuro-neuroscience/200/neuro-211","sections":[{"days":"TR","room":"3024","types":["Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Sophomores only. Not open to those who took BIO 248. Must also register for BIO 211 lab section.","end_time":"10:15:00","meetings":[{"days":"TR","room":"3024","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3024","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Ivan Bochkov"]}]},
