{"code":"PHYED 157","title":"Foundations: Health/Human Pra","department":"Physical Education","credits":0,"description":"Foundations of Health and Human Practices is a physical education course focused on developing lifelong habits of wellness through movement, self-reflection, and mental health awareness. Students explore physical activity, stress management, mindfulness, and personal goal-setting while examining how physical, mental, and emotional health are interconnected. The course encourages self-care, resilience, and informed decision-making to support overall well-being and healthy living.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phyed-physical-education/100/phyed-157","sections":[{"days":"TR","room":"222","types":["Co-Lab Course","First Year Courses","Physical Education Course"],"status":"waitlisted","section":"F01","building":"C.A. Johnson Bldg.","capacity":16,"comments":"This section is open to Health Co-Lab students only.","end_time":"13:45:00","meetings":[{"days":"TR","room":"222","type":"PE","building":"C.A. Johnson Bldg.","end_date":"2026-10-09","end_time":"13:45","start_date":"2026-08-31","start_time":"13:00"}],"start_time":"13:00:00","instructors":["Deidre D. Pierson","Melissa K. Mariano"]}]},
