{"code":"PHYS 100","title":"Survey of Physics I","department":"Physics","credits":1,"description":"The first semester of a year-long sequence (100-205) for pre-med students and other scientists who require a year of physics. Topics include mechanics, fluids and thermodynamics. Emphasis on applications of physics in medicine and in other sciences. Three hours of lecture and three hours of laboratory. First year students need instructors signature to enroll. Prerequisites, knowledge of algebra and trigonometry.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/100/phys-100","sections":[{"days":"MWF","room":"G041","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Students who sign up for PHYS 100 must also sign up for PHYS 100L. First-Year students need permission to register.","end_time":"09:50:00","meetings":[{"days":"MWF","room":"G041","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"G041","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Wren Vetens"]},{"days":"MWF","room":"G041","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"03","building":"Taylor Science Center","capacity":40,"comments":"Students who sign up for PHYS 100 must also sign up for PHYS 100L. First-Year students need permission to register.","end_time":"12:50:00","meetings":[{"days":"MWF","room":"G041","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"},{"days":"M","room":"G041","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"202