{"code":"PHYS 298","title":"Physics Research","department":"Physics","credits":0.25,"description":"Independent work on a research project under supervision of a faculty member. Prerequisites, Consent of instructor. One-quarter or one-half credit per semester. Satisfactory/Unsatisfactory only. Students may repeat 298 for credit, but only a maximum of one-half credit of Physics Research can count towards their concentration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/200/phys-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Seth A. Major"]},{"days":null,"room":null,"types":[],"status":"open","section":"02","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Viva R. Horowitz"]},{"days":null,"room":null,"types":[],"status":"open","section":"03","building":null,"capacity":40,"comments":"Instructor's Signature Required","end_time":null,"meetings":[],"start_time":null,"instructors":["Katherine A. Brown"]},{"days":null,"room":null,"types":[],"status":"open","section":"04","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Charles A. Collett"]}]},
{"code":"PHYS 350","title":"Classical Mechanics","department":"Physics","credits":1,"description":"Principles of classical mechanics, including oscillations, nonlinear dynamics, dynamics of systems of particles, non-inertial reference frames, Hamilton and Lagrangian mechanics, celestial mechanics, rigid body motion and coupled oscillations.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-350","sections":[{"days":"MWF","room":"G047","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MWF","room":"G047","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"G047","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Theo Jacobson"]}]},
{"code":"PHYS 370","title":"Thermodynamics & Stat Phys","department":"Physics","credits":1,"description":"Properties of large-scale systems in terms of a statistical treatment of the motions, interactions and energy levels of particles. Basic probability concepts and the principles of statistical mechanics. Explanation of thermal equilibrium, heat, work and the laws of thermodynamics. Application to various physical systems. Prerequisites, 290.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-370","sections":[{"days":"TR","room":"G047","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"G047","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"G047","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Ariel Rock"]}]},
{"code":"PHYS 390W","title":"Research Seminar","department":"Physics","credits":1,"description":"A series of research projects stressing the integration of theory and experiment. Emphasis on scientific writing, formal oral presentations, use of the current physics literature.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/300/phys-390","sections":[{"days":"MWF","room":"G029","types":["Quantitative & Symbolic R","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":12,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"G029","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"G029","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Viva R. Horowitz"]}]},
{"code":"PHYS 550","title":"Senior Research Project","department":"Physics","credits":1,"description":"Independent research in collaboration with faculty supervisor. Students will give a series of formal oral presentations about their research and will write a comprehensive thesis. Open to senior concentrators or to others with consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/phys-physics/500/phys-550","sections":[{"days":"M","room":"G041","types":["Senior Project"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"17:00:00","meetings":[{"days":"M","room":"G041","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"17:00","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"G042","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Viva R. Horowitz"]}]},
{"code":"PPOL 214","title":"Health Care Systems","department":"Public Policy","credits":1,"description":"An overview and analysis of US health care systems. US health care systems include public health (population-based services) and medical care (individual patients) systems. Topics include development and organization of various public health and medical entities within the United States, strengths and challenges related to cost, quality, and access to these systems, past and present epidemics, and current issues related to health care systems. May not be counted toward the concentration or minor. Not open to students who have taken Bio 216. Next offered TBD.","cross_listed":["BIO 214","SOC 214"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/200/ppol-214","sections":[{"days":"W","room":"211","types":["Co-Lab Course","Proseminar"],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":"Open to Fall 2026 Justice Lab students only.","end_time":"16:00:00","meetings":[{"days":"W","room":"211","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"211","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Herman K. Lehman"]}]},
{"code":"PPOL 251","title":"Intro Public Policy","department":"Public Policy","credits":1,"description":"The study of policy analysis using and comparing a variety of disciplinary and analytic traditions. Consideration of controversies over particular policies at the national and local level and the premises underlying them. Examination of methods and principles used in formulating and evaluating public policy. Open to seniors with consent of instructor. (American Politics)","cross_listed":["GOVT 251"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/200/ppol-251","sections":[{"days":"TR","room":"125","types":["American Studies","Quantitative & Symbolic R","Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to Sophomores & Juniors Only","end_time":"10:15:00","meetings":[{"days":"TR","room":"125","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"125","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Catherine Chen"]}]},
{"code":"PPOL 274W","title":"Justice Lab: Exper & Observ","department":"Public Policy","credits":1,"description":"Students will work two 3 hour, half-day periods each week Requires discussion, journaling and a research paper that synthesizes various parts of the Justice Lab. Must be taken concurrently with other the Justice Lab courses.","cross_listed":["COLEG 274W","SOC 274W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/200/ppol-274","sections":[{"days":"M","room":"251A","types":["Co-Lab Course","Experiential Learning","Jurisprudnc Law Justc Std","Proseminar","Quantitative & Symbolic R","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Fall 2026 Justice Lab students only.","end_time":"21:30:00","meetings":[{"days":"M","room":"251A","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"21:30","start_date":"2026-08-27","start_time":"18:30"}],"start_time":"18:30:00","instructors":["Jeremy Rutter"]}]},
{"code":"PPOL 382W","title":"Public Policy Analysis","department":"Public Policy","credits":1,"description":"This course helps students understand what public policy analysis is, provides them with a toolkit of practical methods for analysis, and emphasizes professional communication of results in writing. Specifically, it introduces students to cost-benefit analysis and natural-experimental approaches for policy evaluation with real-world examples.","cross_listed":["GOVT 382W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/300/ppol-382","sections":[{"days":"TR","room":"109","types":["American Studies","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"109","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"109","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Catherine Chen"]}]},
{"code":"PPOL 412","title":"The Politics of A.I.","department":"Public Policy","credits":1,"description":"This upper-level seminar is structured around three concepts that are central to the politics of AI: algorithms, \"big data,\" and \"humans in the loop.\" Issues discussed include algorithmic discrimination, the state of consent in the age of \"big data,\" and the psychological toll of content moderation on social media. Explicitly interdisciplinary, a variety of methods and academic backgrounds are welcome. The course is speaking intensive. (Political Theory)","cross_listed":["GOVT 412","PHIL 412"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/400/ppol-412","sections":[{"days":"WF","room":"119","types":["Co-Lab Course","Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"List Center","capacity":12,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":"119","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"119","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Ashley E. Gorham"]}]},
{"code":"PPOL 500","title":"Senior Project","department":"Public Policy","credits":1,"description":"A one semester senior project, culminating in a public policy analysis. This is the capstone course in the Public Policy concentration.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/ppol-public-policy/500/ppol-500","sections":[{"days":"F","room":"103","types":["Senior Project"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":"103","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"103","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Catherine Chen"]}]},
{"code":"PSYCH 101","title":"Intro to Psychology","department":"Psychology","credits":1,"description":"An introduction to the science of human behavior. Topics include the nervous system, perception, learning, motivation, cognitive and social development, personality, individual differences, social behavior and psychopathology. In class laboratory exercises to emphasize the use of research methods and data to describe and examine behavior. Some sections may be offered as First-Year Courses.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/100/psych-101","sections":[{"days":"MWF","room":"105","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":"Benedict Hall","capacity":40,"comments":"Open to First Years Only. Students may only take one full credit 100-level PSYCH course.","end_time":"09:50:00","meetings":[{"days":"MWF","room":"105","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"105","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Lok-Kin Yeung"]},{"days":"MWF","room":"207","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"02","building":"Benedict Hall","capacity":40,"comments":"Open to First Years only. Students may only take one full credit 100-level PSYCH course.","end_time":"10:50:00","meetings":[{"days":"MWF","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Alexandra List"]},{"days":"MWF","room":"207","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"03","building":"Benedict Hall","capacity":40,"comments":"Open to First-Years Only. Students may only take one full credit 100-level PSYCH course.","end_time":"11:50:00","meetings":[{"days":"MWF","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Alexandra List"]},{"days":"MWF","room":"2048","types":["Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"04","building":"Taylor Science Center","capacity":40,"comments":"Open to First-Years Only. Students may only take one full credit 100-level PSYCH course.","end_time":"13:50:00","meetings":[{"days":"MWF","room":"2048","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"13:50","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"2048","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Lok-Kin Yeung"]}]},
{"code":"PSYCH 201","title":"Stats & Research Methods","department":"Psychology","credits":1,"description":"The application and interpretation of descriptive and inferential statistics in the study of psychological processes. Some instruction in research design and methodological issues. Students will learn to use the statistical computer program SPSS to analyze data. Topics include the principles of hypothesis testing, t tests, analysis of variance, regression, and some non-parametric statistics. Prerequisites, 101.","cross_listed":["NEURO 201"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-201","sections":[{"days":"MWF","room":"3024","types":["Qlit Course","Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"3024","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"3024","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Siobhan Robinson"]}]},
{"code":"PSYCH 205","title":"Fundamentals of Neurobio","department":"Psychology","credits":1,"description":"Introduction to the field of neuroscience from a biological perspective. In-depth examination of fundamental concepts in neurobiology designed to introduce students to the electrophysiological, chemical and anatomical features of neurons, brain regions and brain circuits.Investigation of the neurobiological basis of behavior through exploration of topics such as neuronal communication, neuroanatomy, sensory and motor systems, learning, motivation, and behavior disorders.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/200/psych-205","sections":[{"days":"MWF","room":"3021","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"09:50:00","meetings":[{"days":"MWF","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"09:50","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"09:00:00","instructors":["Abigail K. Myers"]}]},
{"code":"PSYCH 311W","title":"Soc Psych of Self Lab","department":"Psychology","credits":1,"description":"Theoretical and methodological understanding of the study of the self in social psychology. Topics include organization of self-concept and its effect on information processing; self-awareness; self-esteem maintenance processes; cultural influences; stigmas; and self-regulation. Class time devoted to discussion of research articles. Laboratory component involves conducting two research projects. Data collection, statistical analysis, papers based on findings, oral and poster presentations. Three hours of class and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-311","sections":[{"days":"TR","room":"3039","types":["Quantitative & Symbolic R","Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":18,"comments":"Not open to students who have taken PSYCH 304W, PSYCH 316W, or PSYCH 324W.","end_time":"10:30:00","meetings":[{"days":"TR","room":"3039","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:30","start_date":"2026-08-27","start_time":"09:00"},{"days":"TR","room":"3039","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"10:30"},{"days":"R","room":"3039","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Jennifer L. Borton"]}]},
{"code":"PSYCH 316W","title":"Dev Psych Self Control","department":"Psychology","credits":1,"description":"Theoretical and methodological examination of the psychological processes involved in regulating thoughts, behavior, and emotions. Emphasis on childhood and adolescence. Questions covered will include: What is executive function and how does it develop? What are the consequences of low or delayed self-control abilities across the lifespan? How can we improve self-control? Data collection, statistical analysis, papers based on findings, oral and poster presentations. Three hours of class and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-316","sections":[{"days":"MW","room":"3039","types":["Quantitative & Symbolic R","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Taylor Science Center","capacity":18,"comments":"Exclude PSYCH 304W, 311W, or 324W","end_time":"10:30:00","meetings":[{"days":"MW","room":"3039","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:30","start_date":"2026-08-27","start_time":"09:00"},{"days":"MW","room":"3039","type":"LAB","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"10:30"}],"start_time":"09:00:00","instructors":["Rachel E. White"]}]},
{"code":"PSYCH 356","title":"Social Psychology","department":"Psychology","credits":1,"description":"A survey of social psychology, the study of how and why people behave, think, and feel in social situations. Topics include social cognition, stereotyping and prejudice, the self, social influence, attitudes and persuasion, attraction and relationships, aggression, and helping behavior. Emphasis on experimental research methodology.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-356","sections":[{"days":"TR","room":"2048","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"2048","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"2048","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Fiona Adjei Boateng"]}]},
{"code":"PSYCH 359","title":"Stereotyping & Prejudice","department":"Psychology","credits":1,"description":"In this course we will take a social psychological approach to understanding stereotypes, prejudice(s), and discrimination based on race, ethnicity, gender, sexual orientation, and other group memberships. We will examine classic and contemporary theories and research on topics such as cognitive, motivational, evolutionary, and sociocultural explanations of prejudice; modern forms of prejudice/implicit bias; the impact of prejudice and discrimination on targets of prejudice; and prejudice reduction. Prerequisites, Psych/Neuro 201.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-359","sections":[{"days":"TR","room":"2048","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Seniors, Juniors, & Sophomores Only","end_time":"14:15:00","meetings":[{"days":"TR","room":"2048","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"2048","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Fiona Adjei Boateng"]}]},
{"code":"PSYCH 360","title":"Psychological Testing","department":"Psychology","credits":1,"description":"This course is an in-depth study of methodologies used in clinical psychology research and practice to assess differences among individuals in personality, neuropsychological functioning, intelligence/aptitude, achievement, and forensic issues. Discussion will include the qualities of a good test, how tests are used in current research, as well as limitations and ethical issues involved in clinical assessment.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-360","sections":[{"days":"MW","room":"3021","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Srs., Jrs., and Sophomores","end_time":"15:45:00","meetings":[{"days":"MW","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Tara L. McKee"]}]},
{"code":"PSYCH 380","title":"Research Design","department":"Psychology","credits":1,"description":"Advanced study of psychological research methods, with a focus on critically evaluating original research, independently designing and executing studies, and writing scientific research reports. Topics include reliability and validity, experimental and non-experimental methods, and effective design of studies.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/300/psych-380","sections":[{"days":"MWF","room":"3021","types":["Quantitative & Symbolic R"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":"Open to Seniors, Juniors, & Sophomores","end_time":"11:50:00","meetings":[{"days":"MWF","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Tara L. McKee"]}]},
{"code":"PSYCH 392N","title":"Prin Behavior Analysis","department":"Psychology","credits":1,"description":"Orients students to the concepts, processes and scientific principles of behavior on which the field of applied behavior analysis was founded. Topics of study will include the history and defining features of applied behavior analysis as well as the role of basic principles in producing socially meaningful behavior change (positive and negative reinforcement, punishment, discriminative control of behavior and motivating operations). Prerequisites, Psych/Neuro 201 if the course is to count toward the concentration or minor. Open only to participants in the Cooperative Educational Program at the New England Center for Children.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-new-england-center-for-children/300/psych-392n","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"PSYCH 395N","title":"Behavioral Interventions","department":"Psychology","credits":1,"description":"This course will prepare students to identify, implement, and maintain effective behavioral interventions in applied settings. Specific objectives will include teaching students to select and implement function-based interventions for the reduction of problem behaviors, skills-based prevention strategies, and a variety of behavioral teaching tactics. Tactics for promoting procedural integrity and facilitating the generalization and maintenance of treatment effects will also be reviewed.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-new-england-center-for-children/300/psych-395n","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":5,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":[]}]},
{"code":"PSYCH 455","title":"Field Study in Psych","department":"Psychology","credits":1,"description":"An advanced seminar integrating psychological services with immersive field experience. Students complete eight to ten hours per week in a cooperating local agency or school while participating in a structured seminar examining the theoretical foundations of their applied work.The course emphasizes the provision of psychological, educational, and applied behavioral services, with focused attention on methodological rigor, ethical decision-making, and professional practice in psychotherapy, counseling, and educational psychology. Students complete an extensive written project focused on using psychological research to address real world problems at their site. Open to juniors and seniors only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/psych-psychology/400/psych-455","sections":[{"days":"T","room":"1004","types":[],"status":"open","section":"01","building":"Taylor Science Center","capacity":8,"comments":null,"end_time":"20:00:00","meetings":[{"days":"T","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"20:00","start_date":"2026-08-27","start_time":"18:30"}],"start_time":"18:30:00","instructors":["Erik Jacobson"]}]},
{"code":"PSYCH 500","title":"Senior Project","department":"Psychology","credits":1,"description":"Supervised research on a specific problem in psychology. Psych 500 is only offered in the fall semester. Psych 501 is only offered in the spring semester. Students who will finish their degree requirements in December who want to complete a full-year senior project will need to take Psych 500 in the fall three semesters prior to completion and Psych 501 in the spring two semesters prior to completion. Such students will need to consult with the chair of the Psychology Department in the spring semester prior to taking Psych 500 (i.e., four semesters prior to completion of degree requirements) in order to be included in the advisor assignment process. Students who are unable to follow this timeline will be required to complete a one-semester senior project. Open to senior concentrators.","cross_listed":[],"catalog_url":null,"sections":[{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"02","building":null,"capacity":6,"comments":"Open to Seniors Only","end_time":null,"meetings":[],"start_time":null,"instructors":["Rachel E. White"]},{"days":"F","room":"3021","types":["Senior Project"],"status":"waitlisted","section":"04","building":"Taylor Science Center","capacity":6,"comments":"Open to Seniors Only","end_time":"16:00:00","meetings":[{"days":"F","room":"3021","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"3021","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Alexandra List"]},{"days":null,"room":null,"types":["Senior Project"],"status":"waitlisted","section":"05","building":null,"capacity":6,"comments":"Open to Seniors Only","end_time":null,"meetings":[],"start_time":null,"instructors":["Jennifer L. Borton"]},{"days":null,"room":null,"types":["Senior Project"],"status":"open","section":"07","building":null,"capacity":6,"comments":"Open to Seniors Only","end_time":null,"meetings":[],"start_time":null,"instructors":["Lok-Kin Yeung"]}]},
{"code":"RELST 108","title":"Bad Religion","department":"Religious Studies","credits":1,"description":"Explore various religious communities and practices that have been considered \"irreligious,\" \"superstitious,\" or \"weird,\" from The Church of Jesus Christ of Latter-day Saints to the Church of Satan. This course does not argue that \"bad religion\" exists, but asks instead how critics and outsiders have located particular religious groups and practices beyond the margins of \"real\" or acceptable religion. Tracking various constructions of \"bad religion\" in America from the 1800s to now, we ask what fears and fantasies of religious \"Others\" can reveal about cultural concerns surrounding gender, race, immigration, and more. In addition to secondary sources, we analyze primary sources, popular culture, and news media as influential sites of religious theorizing, construction, and contestation. (Application)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-108","sections":[{"days":"TR","room":"104","types":[],"status":"open","section":"01","building":"Benedict Hall","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"104","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"104","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Shelby King"]}]},
{"code":"RELST 118W","title":"Political Islam","department":"Religious Studies","credits":1,"description":"9/11 catapulted figures such as Osama bin Laden as the face of Political Islam. But there is a longer, complex history behind the relationship between Islam, modern politics, and violence. Through an examination of thinkers such as Sayyid Qutb, Hassan Al-Bana, Zaynab Al-Ghazali, Ayatollah Khomeini, and Abul Ala Maududi, the course will explore their engagement with conceptions of state, nationalism, secularism, democracy, law, gender, and minority rights as they articulated multiple futures for Muslim communities and influenced a variety of political struggles and armed movements. As such, it will think through their intellectual, political, and hermeneutical departures from more traditionalist understandings of Islam and examine the strengths and limitations of their ideas and receptions.","cross_listed":["ASNST 118W","HIST 118W","MEIWS 118W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-118","sections":[{"days":"TR","room":"104","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"11:45:00","meetings":[{"days":"TR","room":"104","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"104","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Suvaid Yaseen"]},{"days":"TR","room":"250","types":["Writing Intensive Courses"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"250","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"250","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Suvaid Yaseen"]}]},
{"code":"RELST 141W","title":"Gurus, Godmen, Godwomen","department":"Religious Studies","credits":1,"description":"What leads people to place unwavering faith in others? What are the ramifications of relationships between everyday people and those they revere as semi-divine? This course explores issues of faith and charisma within weekly case studies of Indian gurus, popularly referred to as \"godmen\" or \"godwomen.\" We will investigate how such figures gain, use, and sometimes lose popularity and power. The primary context of this course is Hindu India, but we also attend to international gurus such as Swami Vivekananda, Osho, and Maharishi Mahesh Yogi (the Beatles' guru). The final week explores the viability of the \"guru\" category to describe popular US influencers such as Oprah Winfrey and Kanye West.","cross_listed":["ASNST 141W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-141","sections":[{"days":"WF","room":"203","types":["Experiential Learning","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":"Open to First Years and Sophomores only","end_time":"14:15:00","meetings":[{"days":"WF","room":"203","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"203","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Corbett Costello"]}]},
{"code":"RELST 157W","title":"The New Testament","department":"Religious Studies","credits":1,"description":"A critical introduction to the literature and history of the Christian New Testament.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-157","sections":[{"days":"MWF","room":"201","types":["Writing Intensive Courses"],"status":"waitlisted","section":"01","building":"Benedict Hall","capacity":18,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"201","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"201","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Sunil Persad"]}]},
{"code":"RELST 160","title":"Everyday Islam","department":"Religious Studies","credits":1,"description":"Introduction to the study of Islam as an everyday lived religion. The course uses interdisciplinary approaches to understanding Muslim beliefs, practices, and institutional practices. Particular focus on questions of revelation, devotion, law, spirituality, and aesthetics. Students develop facility with analyzing Islamic texts and material culture.","cross_listed":["ASNST 160"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-160","sections":[{"days":"MWF","room":"005","types":["Asian Studies"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"10:50:00","meetings":[{"days":"MWF","room":"005","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"005","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Anurag Advani"]}]},
{"code":"RELST 198","title":"Readings in Religious Studies","department":"Religious Studies","credits":0.25,"description":"Religious Studies faculty join with students to read and discuss one important and/or provocative work each semester. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/100/relst-198","sections":[{"days":"W","room":"205","types":[],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":null,"end_time":"12:50:00","meetings":[{"days":"W","room":"205","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"12:50","start_date":"2026-08-27","start_time":"12:00"}],"start_time":"12:00:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"RELST 240","title":"Classical Mythology","department":"Religious Studies","credits":1,"description":"An examination and discussion of the myths of ancient Egypt, Greece and Rome, with particular focus on the reception of these myths in the literature, art, intellectual traditions and social issues of contemporary societies and analysis of how these myths continue to enrich our culture today.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-240","sections":[{"days":"TR","room":"305","types":["Cultural Diversity Course"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"11:45:00","meetings":[{"days":"TR","room":"305","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"305","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Sophia Taborski"]}]},
{"code":"RELST 266","title":"Religion, Ideology, Climate","department":"Religious Studies","credits":1,"description":"This course conceptualizes religion vis-à-vis ideology, limning the contours of these two categories and drawing out similarities and differences between them. We explore the question of what religious and/or ideological ideas lead into our current climate crisis, in the situation we now call the Anthropocene - and ask whether alternate religious and/or ideological ideas can help to lead us out. Over the span of the course, we will read classical authors from religious studies as well as recent work in political philosophy on ideology by theorists in the Marx-egelian critical theory tradition. We will then explore exciting work by degrowth scholars like Kohei Saito. Along the way, some cases will demonstrate the real-world environmental impact of ideological and religious ideas. (Location)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-266","sections":[{"days":"R","room":"207","types":[],"status":"open","section":"01","building":"Benedict Hall","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"16:00:00","meetings":[{"days":"R","room":"207","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"207","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Nan K. Lin"]}]},
{"code":"RELST 278","title":"Reorienting Amer Rel History","department":"Religious Studies","credits":1,"description":"Traditional narratives of American religious history often begin in New England. But what would American religious history look like from the point of view of New Orleans, Louisiana? We consider how American religious history has been shaped by legacies of contact, conflict, and creation among intersecting social identities, colonial powers, cultural histories, and religious concerns in New Orleans and the broader Louisiana Purchase region. We analyze primary sources alongside scholarly works while engaging critical theories and methods in the study of religion to track the mythic dimensions, political aims, and cultural impact of origin stories of American religion. (Location)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/200/relst-278","sections":[{"days":"TR","room":"209","types":[],"status":"open","section":"01","building":"Root Hall","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"209","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"209","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Shelby King"]}]},
{"code":"RELST 303","title":"Corp Buddhism, Money, Kings","department":"Religious Studies","credits":1,"description":"Buddhism in the modern world is often presented as a philosophical religion that promotes spirituality, monasticism, and meditation in pursuit of enlightenment. But Buddhism also has a complex and fascinating longer history as a corporate institution engaged in trade, land management and commerce. This course explains how monks and nuns engaged with the daily hustle and bustle of economic and political life, and the rise of monasteries as corporate institutions. These institutions became major repositories of wealth and influence and their residents were often sophisticated and successful social and economic actors. Learning about the everyday life of Buddhist monasteries offers insights into today's connections between religious, economic, and political life. (Application)","cross_listed":["ASNST 303","HIST 303"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-303","sections":[{"days":"W","room":"122","types":[],"status":"open","section":"01","building":"List Center","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"W","room":"122","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"122","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Abhishek S. Amar"]}]},
{"code":"RELST 304","title":"Religion and Media","department":"Religious Studies","credits":1,"description":"Investigates the role of various media in shaping religious traditions especially Christianity, Judaism, Islam and Hinduism. Beginning with studies of orality and literacy, we move into the impact of the printing press, then electronic media including Internet and video games. (Application)","cross_listed":["CNMS 304"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-304","sections":[{"days":"TR","room":"205","types":["Cinema and Media Studies"],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Years","end_time":"10:15:00","meetings":[{"days":"TR","room":"205","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"205","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["S.B. Rodriguez-Plate"]}]},
{"code":"RELST 305","title":"Animals and Religion","department":"Religious Studies","credits":1,"description":"This course considers how we (as human societies) are to relate to non-human animal life. The first part of the course examines two distinct approaches. One approach considers non-human animal life as fundamentally different in kind from human life: an unbridgeable chasm lies between the human and non-human animal. The other considers human and non-human animal life on a spectrum, emphasizing continuities. The course proceeds by laying out evidence for the \"continuities\" view, and asks: \"Do animals have religion?\" We try to answer this question by working through animal perception, concepts, and proto-language (the evolution of language). Sources come from Christian theology and philosophy, Buddho-Daoist writings, and theoretical biology. Not open to first-year students. (Location; Research & Writing)","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-305","sections":[{"days":"WF","room":"206","types":[],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":"Open to Seniors, Juniors, and Sophomores.","end_time":"14:15:00","meetings":[{"days":"WF","room":"206","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"206","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Nan K. Lin"]}]},
{"code":"RELST 396W","title":"Sem History of Gods","department":"Religious Studies","credits":1,"description":"This historiography course offers a comparative study of how gods have been conceived and venerated in early Mediterranean and Asian societies. Students read liturgical texts, hymns and myths to consider the variety of conceptions of gods and the range of ritual forms used to venerate them across the Euro-Asian continent. Draws from theoretical readings to consider such problems as polytheism and monotheism, myth and ritual. Each student shall determine in consultation with the faculty whether his or her written work will focus on historiography or research. (Interpretation)","cross_listed":["HIST 396W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/300/relst-396","sections":[{"days":"TR","room":"231","types":["Asian Studies","Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":16,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"231","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"231","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Thomas A. Wilson"]}]},
{"code":"RELST 498","title":"Senior Project Seminar","department":"Religious Studies","credits":1,"description":"Students will complete and present a thesis-driven essay based on original research on a religious studies-related question of their own devising. Restricted to senior majors in Religious Studies.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/relst-religious-studies/400/relst-498","sections":[{"days":"WF","room":"206","types":["Senior Project"],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":"Restricted to Senior RELST concentrators","end_time":"15:45:00","meetings":[{"days":"WF","room":"206","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"206","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Nan K. Lin"]}]},
{"code":"RSNST 100W","title":"Murder, Civil War, Opera","department":"Russian Studies","credits":1,"description":"Ivan the Terrible murdered his heir, and left Russia to face economic collapse and mass hunger without a stable government. Then things got really bad. Did Boris Godunov murder Tsarevich Dmitri? Was the First False Dmitri for real? Only Pushkin knew for sure, but it took Modest Mussorgsky to wrap it up in the greatest Russian opera of all time. This course will explore the relationships between history, art and national identity in Russia.","cross_listed":["HIST 100W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/100/rsnst-100","sections":[{"days":"TR","room":"110","types":["Cultural Diversity Course","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Shoshana Keller"]}]},
{"code":"RSNST 157W","title":"Anna Karenina Page & Screen","department":"Russian Studies","credits":1,"description":"Does reading for pleasure differ from reading for a class? How does one interpret texts? What does it mean to read between the lines? Focusing on Leo Tolstoy's Anna Karenina we will learn to identify literary devices, themes, and symbols. Comparing different English versions we'll explore how word choices shape our interpretation. In addition to articulating our views during in-class discussions, we will write compelling interpretive and argumentative essays. Beyond the novel itself, we will consider secondary literature to discuss Anna Karenina's reception history, and consult film adaptations to analyze how text is transformed through cinematic techniques. Knowledge of Russian not required.","cross_listed":["LIT 157W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/100/rsnst-157","sections":[{"days":"TR","room":"1004","types":["First Year Courses","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"Taylor Science Center","capacity":16,"comments":"Open to First Years Only (FYC)","end_time":"10:15:00","meetings":[{"days":"TR","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Ani Abrahamyan"]}]},
{"code":"RSNST 221","title":"Kievan Rus to Russia","department":"Russian Studies","credits":1,"description":"A survey of Slavic and Eurasian history from 9th century Kievan Rus' to the Great Reforms of Alexander II. Emphasis on the development of Rus' from scattered principalities to empire. Students will explore possibilities for a new narrative that includes Ukraine.","cross_listed":["HIST 221"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-221","sections":[{"days":"TR","room":"102","types":["Cultural Diversity Course","Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Years","end_time":"10:15:00","meetings":[{"days":"TR","room":"102","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"102","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Shoshana Keller"]}]},
{"code":"RSNST 286","title":"Dostoevsky's Polyphonic World","department":"Russian Studies","credits":1,"description":"This course offers a deep and wide-ranging exploration of the fiction of the Russian writer, Fyodor Dostoevsky. Students will read \"Notes From the Underground,\" his groundbreaking early novella, as well as two of his great, long-form novels: \"Crime and Punishment\" and \"Brothers Karamazov.\" The theorist Mikhail Bakhtin characterized Dostoevsky's experimental novels as \"polyphonic,\" in that the author let his characters speak as a discordant chorus of distinctive voices, rather than himself speaking in an authoritative, \"monologic,\" authorial voice. Dostoevsky's polyphonic novels gave profound expression to diverse contemporary ideas about politics, philosophy, religion, and human nature, in spite of the author's own vehemently nationalist, imperialist, and xenophobic views.","cross_listed":["LIT 286"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/200/rsnst-286","sections":[{"days":"TR","room":"222","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"15:45:00","meetings":[{"days":"TR","room":"222","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"222","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Jason A. Cieply"]}]},
{"code":"RSNST 550","title":"Senior Seminar","department":"Russian Studies","credits":1,"description":"Independent work consisting of the preparation and presentation of a research paper, translation or other project designed by the student. Requires research using Russian-language sources. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/rsnst-translation/500/rsnst-550","sections":[{"days":null,"room":null,"types":["Cultural Diversity Course","Senior Project"],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Sharon W. Rivera"]}]},
{"code":"RUSSN 110","title":"First-term Russian","department":"Russian","credits":1,"description":"An introduction to the Russian language in a contemporary cultural context. Focus on development of speaking skills in real-life situations.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/100/russn-110","sections":[{"days":"MWF","room":"213","types":[],"status":"open","section":"01","building":"Burke Library","capacity":40,"comments":null,"end_time":"10:50:00","meetings":[{"days":"MWF","room":"213","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"10:50","start_date":"2026-08-27","start_time":"10:00"},{"days":"W","room":"213","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"10:00:00","instructors":["Ani Abrahamyan"]}]},
{"code":"RUSSN 210","title":"Third Term Russian","department":"Russian","credits":1,"description":"This course is a continuation of second-term Russian. Students will continue to master the basics of Russian language across all skills - speaking, listening comprehension, writing, reading, and culture - through intensive use of authentic materials and a strong emphasis on the spoken word. By the end of the semester, you will be familiar with most essential Russian grammar and be able to understand short texts, express yourself in a variety of familiar situations, and understand the language well enough to study in a Russian-speaking environment. If you have prior knowledge of Russian, please contact the instructor to schedule a placement interview.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/200/russn-210","sections":[{"days":"MWF","room":"111","types":[],"status":"open","section":"01","building":"Couper Hall","capacity":40,"comments":null,"end_time":"11:50:00","meetings":[{"days":"MWF","room":"111","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"11:50","start_date":"2026-08-27","start_time":"11:00"},{"days":"T","room":"111","type":"FINAL","building":"Couper Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"11:00:00","instructors":["Jason A. Cieply"]}]},
{"code":"RUSSN 298","title":"Adv Language & Culture","department":"Russian","credits":0.25,"description":"1/4-credit class that must be taken in conjunction with a course in English. Additional weekly session to analyze and discuss the material in the original language. May be repeated for credit.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/200/russn-298","sections":[{"days":null,"room":null,"types":[],"status":"open","section":"01","building":null,"capacity":40,"comments":null,"end_time":null,"meetings":[],"start_time":null,"instructors":["Ani Abrahamyan"]}]},
{"code":"RUSSN 370","title":"Advanced Russian I","department":"Russian","credits":1,"description":"This course focuses on developing advanced speaking, listening, reading, and writing skills. Exposure to primary sources will be paired with explorations of complex grammatical structures to uncover linguistic subtleties and historical specificities of the Russian language. Activities such as close readings, group discussions, debates, in-class presentations, and written assignments will help students develop comprehension and fluency, preparing them to creatively and persuasively express and argue ideas in target language. By the end of the semester, students will also cultivate basic knowledge of academic Russian to critically examine and discuss authentic texts and the social, historical, and aesthetic developments shaping them. May be repeated once for credit, with permission of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/russn-russian-language/300/russn-370","sections":[{"days":"TR","room":"1004","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Taylor Science Center","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"1004","type":"LEC","building":"Taylor Science Center","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"1004","type":"FINAL","building":"Taylor Science Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Ani Abrahamyan"]}]},
{"code":"SOC 101","title":"Introductory Sociology","department":"Sociology","credits":1,"description":"Sociological perspective on human behavior. Classic and contemporary sociological concepts that further an understanding of the structure, process, stability and change of social life. Not open to students who have taken SOC 110 or SOC 126.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/100/soc-101","sections":[{"days":"TR","room":"236","types":["Soc, Struct & Inst Hier"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to 1st Years and Sophomores Only","end_time":"14:15:00","meetings":[{"days":"TR","room":"236","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"236","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Stephen J. Ellingson"]},{"days":"WF","room":"101","types":["Soc, Struct & Inst Hier"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":40,"comments":"Open to 1st Years and Sophomores Only","end_time":"09:45:00","meetings":[{"days":"WF","room":"101","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"101","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Janina L. Selzer"]}]},
{"code":"SOC 212","title":"Sociology of Elites","department":"Sociology","credits":1,"description":"Who rules-and how do they stay on top? This course examines inequality from above, exploring how elites are formed, legitimated, and challenged across diverse settings. Case studies range from Ivy League admissions and Wall Street hiring to technology elites, Russian oligarchs, emergent Chinese elites, Indian caste hierarchies, and royal families in the Gulf. We will explore how class, race, and gender shape the formation of elite groups, their capacity to appropriate resources, and their struggles with rival elites over power and resources. By the end of the course, students will have the analytical tools to understand not just who holds power, but how that power is reproduced, justified, and contested.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-212","sections":[{"days":"TR","room":"102","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"102","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"102","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Harun Ercan"]}]},
{"code":"SOC 214","title":"Health Care Systems","department":"Sociology","credits":1,"description":"An overview and analysis of US health care systems. US health care systems include public health (population-based services) and medical care (individual patients) systems. Topics include development and organization of various public health and medical entities within the United States, strengths and challenges related to cost, quality, and access to these systems, past and present epidemics, and current issues related to health care systems. May not be counted toward the concentration or minor. Not open to students who have taken Bio 216. Next offered TBD.","cross_listed":["BIO 214","PPOL 214"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-214","sections":[{"days":"W","room":"211","types":["Co-Lab Course","Proseminar"],"status":"open","section":"01","building":"Burke Library","capacity":16,"comments":"Open to Fall 2026 Justice Lab students only.","end_time":"16:00:00","meetings":[{"days":"W","room":"211","type":"LEC","building":"Burke Library","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"211","type":"FINAL","building":"Burke Library","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Herman K. Lehman"]}]},
{"code":"SOC 215","title":"Global Race and Sport","department":"Sociology","credits":1,"description":"The course is designed to examine race and diversity issues in the world of sports from the early 20th century to the present. Topics will examine and provide critical inquiry on the impact of race and racism in major world sports and the Olympic movement, including football(soccer), tennis, boxing, cricket, baseball, American football, and athletics. The course is inter-sectional in scope and interrogates issues of masculinity, gender, the structures of power, as well as new forms of global capitalism in sports, and individuals that have personified their areas of sporting achievement.","cross_listed":["AFRST 215"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-215","sections":[{"days":"TR","room":"305","types":[],"status":"waitlisted","section":"01","building":"C.A. Johnson Bldg.","capacity":40,"comments":"Open to 1st Years, Sophomores, & Juniors only","end_time":"15:45:00","meetings":[{"days":"TR","room":"305","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"305","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Nigel D. Westmaas"]}]},
{"code":"SOC 224","title":"Crime, Law, and Inequality","department":"Sociology","credits":1,"description":"This course examines crime, criminalization, and social control from a sociological perspective. Rather than treating crime as simply the violation of law, we examine how crime is socially and politically constructed and how practices of punishment and regulation emerge through broader struggles over power, morality, and social order. Topics include moral panics, addiction and criminalization, policing and surveillance, mass incarceration, organized crime, mafia networks, illicit drug economies, corporate crime, state violence, terrorism, and border enforcement. Students will critically evaluate competing explanations of crime and examine how criminalization and social control both shape and are shaped by relations of power, inequality, governance, and social change.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-224","sections":[{"days":"TR","room":"201","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Benedict Hall","capacity":40,"comments":null,"end_time":"15:45:00","meetings":[{"days":"TR","room":"201","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"201","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Harun Ercan"]}]},
{"code":"SOC 274W","title":"Justice Lab: Exper & Observ","department":"Sociology","credits":1,"description":"Students will work two 3 hour, half-day periods each week Requires discussion, journaling and a research paper that synthesizes various parts of the Justice Lab. Must be taken concurrently with other the Justice Lab courses.","cross_listed":["COLEG 274W","PPOL 274W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-274","sections":[{"days":"M","room":"251A","types":["Co-Lab Course","Experiential Learning","Jurisprudnc Law Justc Std","Proseminar","Quantitative & Symbolic R","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":16,"comments":"Open to Fall 2026 Justice Lab students only.","end_time":"21:30:00","meetings":[{"days":"M","room":"251A","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"21:30","start_date":"2026-08-27","start_time":"18:30"}],"start_time":"18:30:00","instructors":["Jeremy Rutter"]}]},
{"code":"SOC 286","title":"Sociology of Science","department":"Sociology","credits":1,"description":"Science is an important institution in our modern world. This course explores how science is done and how it affects our daily lives. We will put science in its social context, which is important for understanding it as a process and as a powerful force in society. With examples such as controversies over genetic testing and COVID-19, climate change and intellectual property, this course will introduce you to the exciting field of the sociology of science. Prerequisites, 1 course in sociology or consent of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/200/soc-286","sections":[{"days":"MW","room":"218","types":[],"status":"open","section":"01","building":"List Center","capacity":40,"comments":null,"end_time":"09:45:00","meetings":[{"days":"MW","room":"218","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"218","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Timothy Sacco"]}]},
{"code":"SOC 301W","title":"Sociological Theory","department":"Sociology","credits":1,"description":"Examination of classic and contemporary sociological concepts and perspectives. The theorists covered include Marx, Weber, Durkheim, Freud, Mead, Berger and Luckmann, and Foucault. Prerequisites, two sociology courses.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-301","sections":[{"days":"WF","room":"110","types":["Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"14:15:00","meetings":[{"days":"WF","room":"110","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"110","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Mahala D. Stewart"]}]},
{"code":"SOC 302","title":"Research Methods","department":"Sociology","credits":1,"description":"Formulation of a research problem, choice of an appropriate research strategy, execution of that strategy and interpretation of the results. Both qualitative and quantitative methods presented.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-302","sections":[{"days":"TR","room":"203","types":["Experiential Learning","Qlit Course","Quantitative & Symbolic R"],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":40,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":"203","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"203","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Matthew K. Grace"]}]},
{"code":"SOC 325","title":"Medicine in America","department":"Sociology","credits":1,"description":"We take for granted medicine as we know it today, yet at the turn of the 20th century, medical practice could have taken any number of directions. Why did allopathic medicine win out over its competitors to consolidate professional and cultural authority over health? How has the patient-provider relationship evolved from an asymmetric model to one characterized by patient consumerism? How do trainees learn medicine's \"hidden curriculum\"? Looking forward, how will providers fare against challenges to autonomy posed by insurance companies, for-profit hospitals, politicians, and AI? To answer these and related questions, this course draws on empirical studies, historical accounts, and media to examine how the profession of medicine has been constructed, contested, and transformed over time.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-325","sections":[{"days":"TR","room":"203","types":["Co-Lab Course"],"status":"waitlisted","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":"Open to Fall 2026 Justice Lab students only.","end_time":"11:45:00","meetings":[{"days":"TR","room":"203","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"203","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Matthew K. Grace"]}]},
{"code":"SOC 344","title":"Climate Displacement","department":"Sociology","credits":1,"description":"Climate displacement is often an international endeavor. While some individuals adapt to climatic shifts by migrating abroad, others cross borders to find employment where disaster has struck. Again others are hoping for an overhaul of the international refugee system to help preserve their culture and traditions even as they are dispelled from their land. This course takes the exacerbation of old, and the creation of new forms of climate-induced inequality as a starting point to raise questions about the future: What could migration policies organized around the principle of climate justice look like? Where might the threat of displacement lay the foundation for new forms of solidarity? And how can we envision a society that transcends the boundaries of any particular species?","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-344","sections":[{"days":"F","room":"109","types":[],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":"109","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"109","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Janina L. Selzer"]}]},
{"code":"SOC 351","title":"AI and Society","department":"Sociology","credits":1,"description":"Artificial Intelligence (AI) will shape society in profound ways, disrupting fields like higher education, government, science, or medicine. Yet integrating AI responsibly into society remains difficult. This course explores the sociological dimensions of AI, from its historical roots to today's debates around bias, autonomy, and changing human relationships. Students will critically examine how AI systems perceive, reason, and communicate, with emphasis on machine learning's role in driving AI capabilities. The course also unpacks the politics of algorithms, data, and code, and how AI is socially shaped in practice. Drawing on social science research on technology, work, media, and inequalities, students will investigate how AI can be developed and deployed in ways that align with human values and create meaningful social impact.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/300/soc-351","sections":[{"days":"M","room":"123","types":[],"status":"open","section":"01","building":"Kirner-Johnson Building","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"M","room":"123","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"123","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Timothy Sacco"]}]},
{"code":"SOC 549W","title":"Senior Seminar","department":"Sociology","credits":1,"description":"For concentrators preparing to write a thesis. Includes exploration of the range of sociological topics, lectures by departmental faculty on research areas and techniques and workshops on bibliographic methods, site selection and access, and writing of research results. Culminates in presentation of a detailed thesis proposal. Open to senior concentrators only.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/soc-sociology/500/soc-549","sections":[{"days":"TR","room":"119","types":["Writing Intensive Courses"],"status":"open","section":"01","building":"List Center","capacity":20,"comments":"Restricted to Sr. Soc Majors Only","end_time":"15:45:00","meetings":[{"days":"TR","room":"119","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"119","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Stephen J. Ellingson"]},{"days":"WF","room":"124","types":["Writing Intensive Courses"],"status":"open","section":"02","building":"Kirner-Johnson Building","capacity":18,"comments":null,"end_time":"09:45:00","meetings":[{"days":"WF","room":"124","type":"LEC","building":"Kirner-Johnson Building","end_date":"2026-12-11","end_time":"09:45","start_date":"2026-08-27","start_time":"08:30"},{"days":"R","room":"124","type":"FINAL","building":"Kirner-Johnson Building","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"08:30:00","instructors":["Mahala D. Stewart"]}]},
{"code":"THETR 100","title":"Intro to Making Thetr","department":"Theatre","credits":1,"description":"This is the gateway course for all theatre courses. This class combines the study of theatre and drama as it reflects, represents and interprets diverse cultures with a hands-on examination of how theatre is made. Through readings, lectures, discussions and projects the class will explore the ideas, strategies and languages of theatre (acting, directing, playwriting, designing) that theatre artists use to create contemporary theatrical performance.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/100/thetr-100","sections":[{"days":"MW","room":"219","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":20,"comments":"Open to 1st Yrs and Sophomores Only","end_time":"14:15:00","meetings":[{"days":"MW","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"MW","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"MW","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"219","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Craig T. Latrell"]},{"days":"MW","room":"219","types":["First Year Courses","Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"02","building":"Kennedy Center Theatre/Arts","capacity":20,"comments":"Open to First-Years Only (FYC).","end_time":"15:45:00","meetings":[{"days":"MW","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"MW","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"MW","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"219","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Mark M. Cryer"]}]},
{"code":"THETR 105","title":"Intro Thetr Production","department":"Theatre","credits":1,"description":"This will serve as a comprehensive introduction to theatre design and stage craft. Emphasizing hands-on learning experiences, complemented by small group lectures and discussions, the course will explore the fundamentals of stage design, projection design/technologies, set construction, scenic painting and stage and production management and delve into the technologies, tools and techniques used to create the visual world of performance. (Quantitative and Symbolic Reasoning.) 150 minutes of class time and three hours of laboratory.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/100/thetr-105","sections":[{"days":"TR","room":"220","types":["Cinema and Media Studies","Quantitative & Symbolic R"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to 1st Years, Sophomores, & Juniors only","end_time":"11:45:00","meetings":[{"days":"TR","room":"220","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"F","room":"212","type":"LAB","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"},{"days":"T","room":"220","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Tom N. Marhenke"]}]},
{"code":"THETR 141","title":"Production","department":"Theatre","credits":0.5,"description":"The study of theatre through participation (performance, management and/or technical work) in a faculty-directed production. Students must pre-register for this class; for 141F first-year students may register during orientation. Preregistration does not guarantee an acting role. Auditions will take place at the start of the semester, and students not acting will perform a technical/production role. One-half credit. May be repeated for credit.","cross_listed":[],"catalog_url":null,"sections":[{"days":"MTWRF","room":"211","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":40,"comments":"Instructor's Signature Required","end_time":"19:00:00","meetings":[{"days":"MTWRF","room":"211","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"19:00","start_date":"2026-08-27","start_time":"16:15"},{"days":"MTWRF","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"19:00","start_date":"2026-08-27","start_time":"16:15"},{"days":"MTWRF","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"19:00","start_date":"2026-08-27","start_time":"16:15"}],"start_time":"16:15:00","instructors":["Mark M. Cryer","Tobin R. Ost","Jess Buttery"]}]},
{"code":"THETR 201","title":"Acting Style:theatricalsm","department":"Theatre","credits":1,"description":"20th and 21st century performance aesthetics. Practical exploration of non-realistic theatrical methods, emphasizing challenges to Stanislavskian naturalism. Intense text and performance work.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-201","sections":[{"days":"TR","room":"217","types":["Proseminar","Speaking Intensive Course"],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to Seniors, Juniors, & Sophomores Only","end_time":"14:15:00","meetings":[{"days":"TR","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"TR","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"217","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Emily K. Harrison"]}]},
{"code":"THETR 212","title":"Scene Design","department":"Theatre","credits":1,"description":"A lecture/laboratory course in the design of scenery for the stage. Study of principles of composition, materials and fundamentals of drafting and rendering, eventuating in practical scenic designs with floor plans, elevations, sections and models.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-212","sections":[{"days":"MW","room":"220","types":["Quantitative & Symbolic R","Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"15:45:00","meetings":[{"days":"MW","room":"220","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"220","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Tobin R. Ost"]}]},
{"code":"THETR 224","title":"Playwriting","department":"Theatre","credits":1,"description":"Introduction to the techniques of realistic and non-realistic playwriting through a variety of exercises and improvisations, culminating in the writing and staging of a one-act play. While no prior acting experience is required, students participate in staged readings of works.","cross_listed":["CRWR 224"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-224","sections":[{"days":"TR","room":"219","types":["Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., and Sophomores","end_time":"14:15:00","meetings":[{"days":"TR","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"TR","room":"124","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"219","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Craig T. Latrell"]}]},
{"code":"THETR 240","title":"Inter Med:perf, Ritual & Tech","department":"Theatre","credits":1,"description":"This class will cover performance strategies in relationship to digital technology, ritual and the social. We will create collaborative and hybrid work at the intersection of performance, digital media and social practice and map out modes of ritual engagement within these intersections. We will explore \"liveness\" as a digital and/or embodied presence and survey contemporary hybrid performance work. Enrollment 16, No prerequisite.","cross_listed":["ART 240","DARTS 240","MUSIC 240"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/200/thetr-240","sections":[{"days":"R","room":"143","types":["Co-Lab Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":"Open to Seniors, Juniors, Sophomores, & 1st Yrs","end_time":"12:00:00","meetings":[{"days":"R","room":"143","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"12:00","start_date":"2026-08-27","start_time":"09:00"}],"start_time":"09:00:00","instructors":["Anna Huff"]}]},
{"code":"THETR 303","title":"Directing","department":"Theatre","credits":1,"description":"Fundamentals of play direction and script analysis. Study of selected directors and directorial problems; the direction of exercise scenes; and direction of a final scene or one-act for public presentation.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/300/thetr-303","sections":[{"days":"TR","room":"217","types":["Soc, Struct & Inst Hier","Speaking Intensive Course"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":"Open to Srs., Jrs., and Sophomores but Seniors have priority.","end_time":"15:45:00","meetings":[{"days":"TR","room":"217","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"TR","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"TR","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"217","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Craig T. Latrell"]}]},
{"code":"THETR 307","title":"History of Theatre","department":"Theatre","credits":1,"description":"An introduction to the basic texts of theatre history from classical antiquity to the Baroque era, focusing on how Western theatre represents and performs identities race, ethnicity, gender and religion on stage. Places performance within social, cultural and historical contexts, and also provides an introduction to non-Western performance. Prerequisites, Theatre 100, or the signature of instructor.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/300/thetr-307","sections":[{"days":"TR","room":"218","types":["Soc, Struct & Inst Hier"],"status":"open","section":"01","building":"Kennedy Center Theatre/Arts","capacity":16,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"218","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"TR","room":"219","type":"LEC","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"218","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Emily K. Harrison"]}]},
{"code":"THETR 319","title":"Adv Media: Tv Club","department":"Theatre","credits":1,"description":"This advanced Digital Media class will take place between the Digital Arts Lab, and the Photo/Video studio. The focus will be on live mediated performance broadcasts, and will address histories of public access television, broadcast media, media collectives, social and activist video art, and social implications of a recent return back to livestreaming via the internet. Additional topics covered will include digital and analog tools for live video processing, interactivity and studio audiences, serial TV and internet show formats, green screen techniques, and narrative strategies that utilize the integration of bodies, music, props and media in real time. The course will include weekly internet live streams of student work to the Hamilton community and beyond.","cross_listed":["ART 319","DARTS 319"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/thetr-theatre/300/thetr-319","sections":[{"days":"F","room":"143","types":[],"status":"waitlisted","section":"01","building":"Kennedy Center Theatre/Arts","capacity":12,"comments":null,"end_time":"16:00:00","meetings":[{"days":"F","room":"143","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"140","type":"STU","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-11","end_time":"16:00","start_date":"2026-08-27","start_time":"13:00"},{"days":"F","room":"143","type":"FINAL","building":"Kennedy Center Theatre/Arts","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"13:00:00","instructors":["Anna Huff","Emily K. Harrison"]}]},
