{"code":"WMGST 101","title":"Intro Women&gender Studies","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary investigation of past and present views of women and their roles, treatment and experiences in institutions such as the family, the state, the work force, language and sexuality. The diversity of women's experiences across age, class, ethnic, sexual, racial and national lines introduced, and theories of feminism and of women's studies discussed.\n\nMay be offered as a standard course or FYC as well as writing intensive, non-writing intensive, or speaking intensive at the discretion of the department. Please check the schedule for details.","cross_listed":["WMGST 101W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-101","sections":[{"days":"MW","room":"201","types":["Cultural Diversity Course","Diversity Course","Soc, Struct & Inst Hier"],"status":"open","section":"02","building":"Benedict Hall","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr. NOTE: This section is NOT writing intensive.","end_time":"14:15:00","meetings":[{"days":"MW","room":"201","type":"LEC","building":"Benedict Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"R","room":"201","type":"FINAL","building":"Benedict Hall","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"13:00:00","instructors":["Amy Marvin"]}]},
{"code":"WMGST 101W","title":"Intro Women&gender Studies","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary investigation of past and present views of women and their roles, treatment and experiences in institutions such as the family, the state, the work force, language and sexuality. The diversity of women's experiences across age, class, ethnic, sexual, racial and national lines introduced, and theories of feminism and of women's studies discussed.\n\nMay be offered as a standard course or FYC as well as writing intensive, non-writing intensive, or speaking intensive at the discretion of the department. Please check the schedule for details.","cross_listed":["WMGST 101"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-101","sections":[{"days":"TR","room":"111","types":["Cultural Diversity Course","Diversity Course","Proseminar","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"open","section":"01","building":"Couper Hall","capacity":18,"comments":"Open to 1st Years, Sophomores & Juniors Only","end_time":"14:15:00","meetings":[{"days":"TR","room":"111","type":"LEC","building":"Couper Hall","end_date":"2026-12-11","end_time":"14:15","start_date":"2026-08-27","start_time":"13:00"},{"days":"W","room":"111","type":"FINAL","building":"Couper Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"13:00:00","instructors":["Margaret Gentry"]},{"days":"TR","room":"308","types":["Cultural Diversity Course","Diversity Course","Proseminar","Soc, Struct & Inst Hier","Writing Intensive Courses"],"status":"waitlisted","section":"03","building":"C.A. Johnson Bldg.","capacity":18,"comments":"Open 1st Years, Sophomores, & Juniors only","end_time":"15:45:00","meetings":[{"days":"TR","room":"308","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"308","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"12:00","start_date":"2026-12-12","start_time":"09:00"}],"start_time":"14:30:00","instructors":["Taveeshi Singh"]}]},
{"code":"WMGST 145W","title":"City of Women","department":"Women's and Gender Studies","credits":1,"description":"City of Women is a First-Year Course that explores life in modern European cities as experienced by some of the most important female writers of the past century. How does the female perspective challenge a traditionally masculine space that is the city? How does the urban space help women understand themselves? We will focus on the relationship between women and their urban surroundings in a selection of novels, essays, and short stories so as to understand the transformation of gender roles and the modernization of cities from the beginning of the twentieth century to our contemporary world. Taught in English; no knowledge of Italian required.","cross_listed":["ITALN 145W"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/100/wmgst-145","sections":[{"days":"MW","room":"209","types":["First Year Courses","Writing Intensive Courses"],"status":"open","section":"01","building":"Root Hall","capacity":18,"comments":"Open to First-Years Only","end_time":"15:45:00","meetings":[{"days":"MW","room":"209","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"209","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Cecily Cai"]}]},
{"code":"WMGST 202W","title":"Intro LGBTQ Studies","department":"Women's and Gender Studies","credits":1,"description":"This introductory-level writing-intensive course will explore sexuality as a category of analysis that intersects with gender, race, class, nationality, and religion. The course will include key historical texts in the field of LGBTQ Studies, as well as current developments. Through writing a series of letters, students will practice the feminist model of combining personal, political, and scholarly perspectives. You will learn to critically analyze prevailing normative assumptions, social and cultural institutions, your own life, Hamilton College, and the wider community.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/200/wmgst-202","sections":[{"days":"MW","room":"101","types":["Diversity Course","Writing Intensive Courses"],"status":"open","section":"01","building":"C.A. Johnson Bldg.","capacity":18,"comments":null,"end_time":"15:45:00","meetings":[{"days":"MW","room":"101","type":"LEC","building":"C.A. Johnson Bldg.","end_date":"2026-12-11","end_time":"15:45","start_date":"2026-08-27","start_time":"14:30"},{"days":"F","room":"101","type":"FINAL","building":"C.A. Johnson Bldg.","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"14:30:00","instructors":["Amy Marvin"]}]},
{"code":"WMGST 278","title":"Rethinking the Romance","department":"Women's and Gender Studies","credits":1,"description":"A study of the ways in which literary works shape and are shaped by conventional beliefs about love and happiness. How do representations of romance serve aesthetic and political ends? How does fiction navigate the gap between truth (what is real) and desire (what is wished for)? Special attention to texts that reflect on the (sexual, psychological, and/or political) \"abnormal.\" Readings will include theory as well as literary texts by such authors as Diderot, Sand, Austen, Wilde, and Moravia.","cross_listed":["LIT 278"],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/200/wmgst-278","sections":[{"days":"TR","room":"229","types":[],"status":"open","section":"01","building":"List Center","capacity":40,"comments":"Open to Srs., Jrs., Soph., & 1st Yr","end_time":"10:15:00","meetings":[{"days":"TR","room":"229","type":"LEC","building":"List Center","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"229","type":"FINAL","building":"List Center","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Suzanne Taylor"]}]},
{"code":"WMGST 301W","title":"Fem Methodological Persp","department":"Women's and Gender Studies","credits":1,"description":"An interdisciplinary exploration of feminist methods of social analysis. Emphasis on how feminist inquiry has transformed how we think about and study gender in the sciences, social sciences, arts and humanities.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/300/wmgst-301","sections":[{"days":"TR","room":"206","types":["Cultural Diversity Course","Writing Intensive Courses"],"status":"open","section":"01","building":"Root Hall","capacity":18,"comments":null,"end_time":"10:15:00","meetings":[{"days":"TR","room":"206","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"10:15","start_date":"2026-08-27","start_time":"09:00"},{"days":"R","room":"206","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"22:00","start_date":"2026-12-12","start_time":"19:00"}],"start_time":"09:00:00","instructors":["Margaret Gentry"]}]},
{"code":"WMGST 410","title":"Transnational Feminist Praxis","department":"Women's and Gender Studies","credits":1,"description":"Seminar exploring contemporary and historical struggles for gender justice as intersecting with global forces of colonialism, imperialism, neoliberal capitalism, carcerality and militarism. We will examine how (1) economies, states and security apparatuses shape the movement and flow of peoples' lives and resistance to structures of oppression across axes of gender, race, class, caste, sexuality and disability; and (2) how feminist scholars and activists theorize the workings and effects of national and transnational exploitative power regimes in relation to peoples' organized struggles against these regimes.","cross_listed":[],"catalog_url":"https://hamilton.smartcatalogiq.com/en/current/college-catalogue/courses/wmgst-womens-and-gender-studies/400/wmgst-410","sections":[{"days":"TR","room":"205","types":[],"status":"open","section":"01","building":"Root Hall","capacity":12,"comments":null,"end_time":"11:45:00","meetings":[{"days":"TR","room":"205","type":"LEC","building":"Root Hall","end_date":"2026-12-11","end_time":"11:45","start_date":"2026-08-27","start_time":"10:30"},{"days":"T","room":"205","type":"FINAL","building":"Root Hall","end_date":"2026-12-18","end_time":"17:00","start_date":"2026-12-12","start_time":"14:00"}],"start_time":"10:30:00","instructors":["Taveeshi Singh"]}]}
]$catalog$::jsonb as doc),
c as (
  select * from jsonb_to_recordset((select doc from catalog)) as x(
    code text, title text, department text, credits numeric, description text,
    cross_listed text[], catalog_url text, sections jsonb)
),
ins as (
  insert into public.courses (term_id, code, title, department, credits, description, cross_listed, catalog_url)
  select '2026FA', code, title, department, credits, description, coalesce(cross_listed, '{}'), catalog_url from c
  returning id, code
)
insert into public.sections (course_id, section, instructors, days, start_time, end_time, building, room, capacity, status, meetings, comments, types)
select ins.id, s.section, coalesce(s.instructors, '{}'), s.days, s.start_time, s.end_time, s.building, s.room,
       s.capacity, s.status, coalesce(s.meetings, '[]'), s.comments, coalesce(s.types, '{}')
from c
join ins using (code)
cross join lateral jsonb_to_recordset(c.sections) as s(
  section text, instructors text[], days text, start_time time, end_time time, building text, room text,
  capacity integer, status text, meetings jsonb, comments text, types text[]);
